RDMContent.register("family",{"schemaVersion":1,"topics":[{"id":"visits","title":{"es":"Organizar una visita","sk":"Dohodnúť návštevu"},"note":{"es":"Propón algo concreto y deja espacio para que la otra persona lo cambie.","sk":"Navrhnite niečo konkrétne a nechajte druhému priestor na zmenu."}},{"id":"arrivals","title":{"es":"Llegar y recibir","sk":"Príchod a privítanie"},"note":{"es":"Al recibir a alguien, orienta y ofrece sin dar nada por supuesto.","sk":"Pri privítaní poraďte a ponúknite pomoc bez zbytočných predpokladov."}},{"id":"table","title":{"es":"En la mesa","sk":"Pri stole"},"note":{"es":"Habla de gustos y cantidades con naturalidad; se puede rechazar algo con amabilidad.","sk":"O chutiach a množstve hovorte prirodzene, odmietnuť sa dá aj milo."}},{"id":"kitchen","title":{"es":"Cocinar juntos","sk":"Spoločné varenie"},"note":{"es":"Reparte tareas concretas y comprueba antes de cambiar una receta.","sk":"Rozdeľte konkrétne úlohy a pred zmenou receptu sa opýtajte."}},{"id":"home","title":{"es":"Compartir la casa","sk":"Spoločná domácnosť"},"note":{"es":"Pedir colaboración funciona mejor con una tarea clara que con un reproche general.","sk":"O spoluprácu požiadajte konkrétnou úlohou namiesto všeobecnej výčitky."}},{"id":"plans","title":{"es":"Decidir qué hacer","sk":"Rozhodnúť sa, čo podniknúť"},"note":{"es":"Una propuesta puede ser flexible: ofrece una alternativa y acepta un cambio.","sk":"Návrh môže byť pružný, ponúknite alternatívu a prijmite zmenu."}},{"id":"errands","title":{"es":"Recados y favores","sk":"Vybavovanie a láskavosti"},"note":{"es":"Aclara qué necesitas y permite que la otra persona diga que no puede.","sk":"Povedzte jasne, čo potrebujete, a nechajte druhému možnosť odmietnuť."}},{"id":"news","title":{"es":"Ponerse al día","sk":"Povedať si novinky"},"note":{"es":"Pregunta sin interrogar y distingue lo que sabes de lo que solo te han contado.","sk":"Pýtajte sa bez vypočúvania a rozlišujte vlastné informácie od sprostredkovaných."}},{"id":"wellbeing","title":{"es":"Cómo te encuentras","sk":"Ako sa cítiš"},"note":{"es":"Pregunta por la experiencia de la persona y escucha lo que necesita.","sk":"Pýtajte sa na to, ako sa človek cíti, a počúvajte, čo potrebuje."}},{"id":"support","title":{"es":"Escuchar y apoyar","sk":"Počúvať a podporiť"},"note":{"es":"Antes de aconsejar, averigua si la otra persona quiere ideas o solo compañía.","sk":"Pred radou zistite, či druhý chce návrhy alebo len spoločnosť."}},{"id":"boundaries","title":{"es":"Poner límites con cariño","sk":"Láskavo určiť hranice"},"note":{"es":"Un límite claro puede ser amable: di lo que puedes ofrecer y lo que no.","sk":"Jasná hranica môže byť láskavá, povedzte, čo môžete ponúknuť a čo nie."}},{"id":"disagreements","title":{"es":"Discrepar y reparar","sk":"Nesúhlasiť a napraviť nedorozumenie"},"note":{"es":"Separa la idea de la persona y comprueba qué quiso decir antes de responder.","sk":"Oddeľte názor od človeka a pred odpoveďou si overte, čo chcel povedať."}},{"id":"memories","title":{"es":"Recuerdos y otras épocas","sk":"Spomienky a iné obdobia"},"note":{"es":"Puedes contar un recuerdo sin exigir que todos lo recuerden igual.","sk":"Spomienku môžete rozprávať bez očakávania, že si ju všetci pamätajú rovnako."}},{"id":"interests","title":{"es":"Libros, ideas y aficiones","sk":"Knihy, myšlienky a záľuby"},"note":{"es":"Pide razones y ejemplos; un gusto distinto también puede abrir una buena charla.","sk":"Pýtajte sa na dôvody a príklady, aj odlišný vkus môže otvoriť dobrý rozhovor."}},{"id":"outings","title":{"es":"Paseos y salidas","sk":"Prechádzky a spoločné aktivity"},"note":{"es":"Hablad del ritmo y de las preferencias antes de dar por hecho el plan.","sk":"O tempe a záľubách hovorte skôr, než budete plán považovať za samozrejmý."}},{"id":"travel","title":{"es":"Viajar en familia","sk":"Spoločné cestovanie"},"note":{"es":"Comparte la organización y confirma los detalles que pueden causar confusión.","sk":"Podeľte si organizáciu a overte podrobnosti, ktoré môžu viesť k nedorozumeniu."}},{"id":"calls","title":{"es":"Llamadas y mensajes","sk":"Telefonáty a správy"},"note":{"es":"Si falla la comunicación, confirma lo importante en vez de fingir que has entendido.","sk":"Ak komunikácia zlyhá, overte si dôležité veci namiesto predstierania, že rozumiete."}},{"id":"celebrations","title":{"es":"Celebrar y agradecer","sk":"Oslavy a poďakovanie"},"note":{"es":"Agradece algo concreto; una celebración puede ser sencilla y compartida.","sk":"Poďakujte sa za niečo konkrétne, oslava môže byť jednoduchá a spoločná."}},{"id":"younger","title":{"es":"Hablar con los más jóvenes","sk":"Rozhovory s mladšími"},"note":{"es":"La curiosidad sincera abre más conversación que fingir que ya conoces su mundo.","sk":"Úprimná zvedavosť otvára lepší rozhovor než predstieranie, že už poznáte ich svet."}},{"id":"farewells","title":{"es":"Despedirse y seguir en contacto","sk":"Rozlúčiť sa a zostať v kontakte"},"note":{"es":"Cierra el encuentro con algo concreto y sin prometer lo que no sabes si podrás cumplir.","sk":"Stretnutie uzavrite niečím konkrétnym a nesľubujte to, čo možno nesplníte."}}],"entries":[{"id":"family-visits-001","prompt":{"es":"¿Os va bien el domingo?","sk":"Vyhovuje vám nedeľa?"},"reply":{"es":"El domingo sí; el sábado tenemos un compromiso.","sk":"Nedeľa áno, v sobotu už niečo máme."},"topic":"visits"},{"id":"family-visits-002","prompt":{"es":"Podríamos vernos después de comer.","sk":"Mohli by sme sa stretnúť po obede."},"reply":{"es":"Estupendo, así no vamos con prisas.","sk":"Výborne, aspoň sa nebudeme ponáhľať."},"topic":"visits"},{"id":"family-visits-003","prompt":{"es":"¿A qué hora pensáis venir?","sk":"O koľkej plánujete prísť?"},"reply":{"es":"Sobre las seis, si no hay mucho tráfico.","sk":"Okolo šiestej, ak nebude veľká premávka."},"topic":"visits"},{"id":"family-visits-004","prompt":{"es":"Este fin de semana estamos fuera.","sk":"Tento víkend sme preč."},"reply":{"es":"Pues lo dejamos para el siguiente.","sk":"Tak to necháme na ďalší."},"topic":"visits"},{"id":"family-visits-005","prompt":{"es":"¿Te importa que venga también mi hermana?","sk":"Nevadí ti, ak príde aj moja sestra?"},"reply":{"es":"Al contrario, hace tiempo que no la veo.","sk":"Práve naopak, dávno som ju nevidel."},"topic":"visits"},{"id":"family-visits-006","prompt":{"es":"Nos gustaría pasar a saludar.","sk":"Radi by sme sa zastavili pozdraviť."},"reply":{"es":"Venid cuando queráis; estaremos en casa.","sk":"Príďte, kedy chcete, budeme doma."},"topic":"visits"},{"id":"family-visits-007","prompt":{"es":"¿Reservamos la tarde entera?","sk":"Necháme si voľné celé popoludnie?"},"reply":{"es":"Con un par de horas nos basta.","sk":"Stačí nám pár hodín."},"topic":"visits"},{"id":"family-visits-008","prompt":{"es":"No sé si llegaremos antes de las ocho.","sk":"Neviem, či prídeme pred ôsmou."},"reply":{"es":"No pasa nada; os esperamos para cenar.","sk":"Nevadí, počkáme na vás s večerou."},"topic":"visits"},{"id":"family-visits-009","prompt":{"es":"¿Preferís venir aquí o que vayamos nosotros?","sk":"Radšej prídete sem alebo máme prísť my?"},"reply":{"es":"Esta vez vamos nosotros, que os toca descansar.","sk":"Tentoraz prídeme my, vy si oddýchnite."},"topic":"visits"},{"id":"family-visits-010","prompt":{"es":"Tengo una cita a las cinco.","sk":"O piatej mám dohodnuté stretnutie."},"reply":{"es":"Entonces quedamos por la mañana.","sk":"Tak sa stretneme dopoludnia."},"topic":"visits"},{"id":"family-visits-011","prompt":{"es":"¿Cuántos vais a ser al final?","sk":"Koľkí nakoniec prídete?"},"reply":{"es":"Seremos cuatro; Ana no puede venir.","sk":"Budeme štyria, Ana nemôže prísť."},"topic":"visits"},{"id":"family-visits-012","prompt":{"es":"Igual nos acercamos mañana.","sk":"Možno sa zajtra zastavíme."},"reply":{"es":"Mándame un mensaje antes de salir.","sk":"Napíš mi správu pred odchodom."},"topic":"visits"},{"id":"family-visits-013","prompt":{"es":"¿Y si invitamos también a los vecinos?","sk":"Čo keby sme pozvali aj susedov?"},"reply":{"es":"Buena idea, pero avísales con tiempo.","sk":"Dobrý nápad, ale daj im včas vedieť."},"topic":"visits"},{"id":"family-visits-014","prompt":{"es":"Me viene mejor una visita corta.","sk":"Viac mi vyhovuje krátka návšteva."},"reply":{"es":"Claro, tomamos un café y ya está.","sk":"Jasné, dáme si kávu a hotovo."},"topic":"visits"},{"id":"family-visits-015","prompt":{"es":"¿Os quedáis a dormir?","sk":"Zostanete na noc?"},"reply":{"es":"Sí, si no os supone mucho lío.","sk":"Áno, ak vám tým veľmi neskomplikujeme život."},"topic":"visits"},{"id":"family-visits-016","prompt":{"es":"Hemos cambiado de planes.","sk":"Zmenili sme plány."},"reply":{"es":"Dime qué día os encaja ahora.","sk":"Povedz, ktorý deň vám teraz vyhovuje."},"topic":"visits"},{"id":"family-visits-017","prompt":{"es":"¿Hace falta llevar algo?","sk":"Treba niečo priniesť?"},"reply":{"es":"Traed solo lo que os apetezca beber.","sk":"Prineste si len to, čo chcete piť."},"topic":"visits"},{"id":"family-visits-018","prompt":{"es":"La semana que viene la tengo bastante libre.","sk":"Budúci týždeň mám dosť voľný."},"reply":{"es":"Pues buscamos un día con calma.","sk":"Tak si v pokoji vyberieme deň."},"topic":"visits"},{"id":"family-visits-019","prompt":{"es":"¿Lo confirmamos el jueves?","sk":"Potvrdíme si to vo štvrtok?"},"reply":{"es":"Vale, para entonces sabré mi horario.","sk":"Dobre, dovtedy budem vedieť svoj rozvrh."},"topic":"visits"},{"id":"family-visits-020","prompt":{"es":"No queremos presentarnos sin avisar.","sk":"Nechceme sa objaviť bez ohlásenia."},"reply":{"es":"Con que llaméis un rato antes, basta.","sk":"Stačí, keď chvíľu predtým zavoláte."},"topic":"visits"},{"id":"family-visits-021","prompt":{"es":"¿Podemos adelantarlo media hora?","sk":"Môžeme to posunúť o pol hodiny skôr?"},"reply":{"es":"Sí, me organizo y estoy listo antes.","sk":"Áno, zariadim sa a budem pripravený skôr."},"topic":"visits"},{"id":"family-visits-022","prompt":{"es":"La próxima vez os invitamos nosotros.","sk":"Nabudúce vás pozveme my."},"reply":{"es":"Hecho, así vamos alternando.","sk":"Dohodnuté, aspoň sa prestriedame."},"topic":"visits"},{"id":"family-visits-023","prompt":{"es":"¿Quieres que lo dejemos para otro día?","sk":"Chceš to nechať na iný deň?"},"reply":{"es":"Te lo agradezco; hoy voy muy justo.","sk":"Budem rád, dnes vôbec nestíham."},"topic":"visits"},{"id":"family-visits-024","prompt":{"es":"Solo podremos pasar un momento.","sk":"Budeme sa môcť zastaviť len na chvíľu."},"reply":{"es":"Un rato juntos también merece la pena.","sk":"Aj krátka spoločná chvíľa stojí za to."},"topic":"visits"},{"id":"family-visits-025","prompt":{"es":"¿Quedamos ya o esperamos a saberlo todos?","sk":"Dohodneme sa už alebo počkáme, kým budú všetci vedieť?"},"reply":{"es":"Fijemos una fecha y vemos quién puede.","sk":"Určime dátum a uvidíme, kto môže."},"topic":"visits"},{"id":"family-arrivals-001","prompt":{"es":"¡Ya estamos abajo!","sk":"Už sme dole!"},"reply":{"es":"Os abro; es el segundo piso.","sk":"Otvorím vám, je to druhé poschodie."},"topic":"arrivals"},{"id":"family-arrivals-002","prompt":{"es":"Creo que nos hemos pasado de portal.","sk":"Asi sme prešli správny vchod."},"reply":{"es":"Volved a la esquina; es la puerta azul.","sk":"Vráťte sa na roh, sú to modré dvere."},"topic":"arrivals"},{"id":"family-arrivals-003","prompt":{"es":"¿Dónde podemos aparcar?","sk":"Kde môžeme zaparkovať?"},"reply":{"es":"Detrás del mercado suele haber sitio.","sk":"Za tržnicou býva miesto."},"topic":"arrivals"},{"id":"family-arrivals-004","prompt":{"es":"Perdona el retraso, había atasco.","sk":"Prepáč meškanie, bola zápcha."},"reply":{"es":"Tranquilo, acabamos de llegar también.","sk":"Pokojne, aj my sme práve prišli."},"topic":"arrivals"},{"id":"family-arrivals-005","prompt":{"es":"¿Se puede dejar el coche aquí?","sk":"Môže tu zostať auto?"},"reply":{"es":"Solo para descargar; luego hay que moverlo.","sk":"Len na vyloženie, potom ho treba presunúť."},"topic":"arrivals"},{"id":"family-arrivals-006","prompt":{"es":"Traemos demasiadas bolsas.","sk":"Máme priveľa tašiek."},"reply":{"es":"Dejadlas ahí y os ayudo a subirlas.","sk":"Nechajte ich tam, pomôžem vám ich vyniesť."},"topic":"arrivals"},{"id":"family-arrivals-007","prompt":{"es":"¿Te quitas los zapatos al entrar?","sk":"Vyzúvaš sa pri vstupe?"},"reply":{"es":"Sí, los dejo junto a la puerta.","sk":"Áno, nechávam ich pri dverách."},"topic":"arrivals"},{"id":"family-arrivals-008","prompt":{"es":"No encuentro el timbre con vuestro nombre.","sk":"Neviem nájsť zvonček s vaším menom."},"reply":{"es":"Pulsa el que pone segundo derecha.","sk":"Stlač ten s označením druhé vpravo."},"topic":"arrivals"},{"id":"family-arrivals-009","prompt":{"es":"¡Qué alegría verte por aquí!","sk":"Tak rád ťa tu vidím!"},"reply":{"es":"Tenía muchas ganas de pasar un rato contigo.","sk":"Veľmi som s tebou chcel stráviť chvíľu."},"topic":"arrivals"},{"id":"family-arrivals-010","prompt":{"es":"Venimos un poco acalorados.","sk":"Sme trochu rozhorúčení."},"reply":{"es":"Sentaos, ahora os traigo agua.","sk":"Sadnite si, hneď vám prinesiem vodu."},"topic":"arrivals"},{"id":"family-arrivals-011","prompt":{"es":"¿Dónde dejo el abrigo?","sk":"Kam mám dať kabát?"},"reply":{"es":"En la silla de la entrada, si quieres.","sk":"Ak chceš, na stoličku pri vchode."},"topic":"arrivals"},{"id":"family-arrivals-012","prompt":{"es":"El ascensor no funciona.","sk":"Výťah nefunguje."},"reply":{"es":"Voy a bajar a echaros una mano.","sk":"Zídem dole a pomôžem vám."},"topic":"arrivals"},{"id":"family-arrivals-013","prompt":{"es":"¿Habéis encontrado bien la casa?","sk":"Našli ste dom bez problémov?"},"reply":{"es":"Sí, la indicación de la farmacia nos ayudó.","sk":"Áno, pomohla nám rada s lekárňou."},"topic":"arrivals"},{"id":"family-arrivals-014","prompt":{"es":"Nos ha pillado la lluvia.","sk":"Zastihol nás dážď."},"reply":{"es":"Os dejo unas toallas para secaros.","sk":"Dám vám uteráky, aby ste sa osušili."},"topic":"arrivals"},{"id":"family-arrivals-015","prompt":{"es":"¿Te importa si abro la ventana?","sk":"Nevadí ti, ak otvorím okno?"},"reply":{"es":"Adelante, aquí se está un poco cargado.","sk":"Pokojne, je tu trochu dusno."},"topic":"arrivals"},{"id":"family-arrivals-016","prompt":{"es":"Me he dejado el bolso en el coche.","sk":"Nechala som si kabelku v aute."},"reply":{"es":"Te acompaño a buscarlo.","sk":"Pôjdem po ňu s tebou."},"topic":"arrivals"},{"id":"family-arrivals-017","prompt":{"es":"¿Este es vuestro nuevo piso?","sk":"Toto je váš nový byt?"},"reply":{"es":"Sí, todavía nos faltan unas cuantas cosas.","sk":"Áno, ešte nám chýba dosť vecí."},"topic":"arrivals"},{"id":"family-arrivals-018","prompt":{"es":"Qué bien huele al entrar.","sk":"Ako pekne to tu pri vstupe vonia."},"reply":{"es":"He puesto pan a tostar.","sk":"Dala som opekať chlieb."},"topic":"arrivals"},{"id":"family-arrivals-019","prompt":{"es":"¿Dónde está el baño, por favor?","sk":"Kde je, prosím, kúpeľňa?"},"reply":{"es":"Al fondo del pasillo, a la izquierda.","sk":"Na konci chodby vľavo."},"topic":"arrivals"},{"id":"family-arrivals-020","prompt":{"es":"Nos hemos cruzado con tu hermano abajo.","sk":"Dole sme stretli tvojho brata."},"reply":{"es":"Ha salido a comprar hielo.","sk":"Išiel kúpiť ľad."},"topic":"arrivals"},{"id":"family-arrivals-021","prompt":{"es":"¿Prefieres sentarte aquí o en el sofá?","sk":"Radšej si sadneš sem alebo na pohovku?"},"reply":{"es":"Aquí estoy bien, gracias.","sk":"Tu je mi dobre, ďakujem."},"topic":"arrivals"},{"id":"family-arrivals-022","prompt":{"es":"Vaya, hemos llegado los primeros.","sk":"Aha, prišli sme prví."},"reply":{"es":"Sí, los demás están de camino.","sk":"Áno, ostatní sú na ceste."},"topic":"arrivals"},{"id":"family-arrivals-023","prompt":{"es":"¿Has cambiado la cerradura?","sk":"Vymenil si zámok?"},"reply":{"es":"Sí, por eso la llave antigua ya no sirve.","sk":"Áno, preto už starý kľúč nefunguje."},"topic":"arrivals"},{"id":"family-arrivals-024","prompt":{"es":"Te he traído unas flores.","sk":"Priniesla som ti kvety."},"reply":{"es":"¡Qué detalle! Voy a buscar un jarrón.","sk":"To je milé! Idem nájsť vázu."},"topic":"arrivals"},{"id":"family-arrivals-025","prompt":{"es":"No hace falta que salgas a recibirnos.","sk":"Nemusíš nám ísť naproti."},"reply":{"es":"Vale, os espero con la puerta abierta.","sk":"Dobre, počkám vás pri otvorených dverách."},"topic":"arrivals"},{"id":"family-table-001","prompt":{"es":"¿Te sirvo un poco más?","sk":"Dám ti ešte trochu?"},"reply":{"es":"Solo un poquito, que estoy bastante lleno.","sk":"Len trošku, už som dosť sýty."},"topic":"table"},{"id":"family-table-002","prompt":{"es":"¿Me pasas el pan?","sk":"Podáš mi chlieb?"},"reply":{"es":"Claro, lo tienes justo a tu lado.","sk":"Jasné, máš ho hneď vedľa seba."},"topic":"table"},{"id":"family-table-003","prompt":{"es":"Esto está buenísimo.","sk":"Toto je výborné."},"reply":{"es":"Me alegro; era la primera vez que lo hacía.","sk":"Som rád, robil som to prvýkrát."},"topic":"table"},{"id":"family-table-004","prompt":{"es":"¿Lleva frutos secos esta salsa?","sk":"Sú v tejto omáčke orechy?"},"reply":{"es":"Sí, lleva almendras; te traigo otra.","sk":"Áno, sú tam mandle, prinesiem ti inú."},"topic":"table"},{"id":"family-table-005","prompt":{"es":"No me pongas mucho, por favor.","sk":"Nedávaj mi veľa, prosím."},"reply":{"es":"Te sirvo poco y luego repites si quieres.","sk":"Dám ti málo a potom si môžeš pridať."},"topic":"table"},{"id":"family-table-006","prompt":{"es":"¿Alguien quiere agua con gas?","sk":"Chce niekto perlivú vodu?"},"reply":{"es":"Yo sí, con un poco de hielo.","sk":"Ja áno, s trochou ľadu."},"topic":"table"},{"id":"family-table-007","prompt":{"es":"Creo que le falta sal.","sk":"Myslím, že tomu chýba soľ."},"reply":{"es":"La sal está en la mesa; añade a tu gusto.","sk":"Soľ je na stole, pridaj si podľa chuti."},"topic":"table"},{"id":"family-table-008","prompt":{"es":"¿Esperamos a Marta para empezar?","sk":"Počkáme s jedlom na Martu?"},"reply":{"es":"Ha dicho que empecemos, que llega tarde.","sk":"Odkázala, nech začneme, lebo bude meškať."},"topic":"table"},{"id":"family-table-009","prompt":{"es":"¿Quién quiere probar la ensalada?","sk":"Kto chce ochutnať šalát?"},"reply":{"es":"Yo pruebo un poco, tiene buena pinta.","sk":"Ja ochutnám trochu, vyzerá dobre."},"topic":"table"},{"id":"family-table-010","prompt":{"es":"Se me ha enfriado la sopa.","sk":"Vychladla mi polievka."},"reply":{"es":"La calentamos un momento y listo.","sk":"Na chvíľu ju zohrejeme a hotovo."},"topic":"table"},{"id":"family-table-011","prompt":{"es":"¿Tú comes pescado?","sk":"Jedávaš ryby?"},"reply":{"es":"Sí, pero prefiero que no tenga muchas espinas.","sk":"Áno, ale radšej také, ktoré nemajú veľa kostí."},"topic":"table"},{"id":"family-table-012","prompt":{"es":"Hoy no me apetece vino.","sk":"Dnes nemám chuť na víno."},"reply":{"es":"Sin problema, hay agua y zumo.","sk":"Bez problémov, máme vodu aj džús."},"topic":"table"},{"id":"family-table-013","prompt":{"es":"¿Qué es lo que lleva por encima?","sk":"Čo je to navrchu?"},"reply":{"es":"Un poco de perejil y ralladura de limón.","sk":"Trochu petržlenovej vňate a citrónovej kôry."},"topic":"table"},{"id":"family-table-014","prompt":{"es":"Me he pasado con la pimienta.","sk":"Prehnal som to s čiernym korením."},"reply":{"es":"A mí me gusta así, pero podemos suavizarlo.","sk":"Mne to tak chutí, ale môžeme to zjemniť."},"topic":"table"},{"id":"family-table-015","prompt":{"es":"¿Te guardo algo para después?","sk":"Odložím ti niečo na neskôr?"},"reply":{"es":"Sí, un poco de arroz, si sobra.","sk":"Áno, trochu ryže, ak zostane."},"topic":"table"},{"id":"family-table-016","prompt":{"es":"¿Este plato es típico de aquí?","sk":"Je toto jedlo odtiaľto?"},"reply":{"es":"En esta zona lo preparan bastante.","sk":"V tejto oblasti ho pripravujú dosť často."},"topic":"table"},{"id":"family-table-017","prompt":{"es":"¿Retiro ya los platos?","sk":"Môžem už odpratať taniere?"},"reply":{"es":"Espera un momento, todavía estoy terminando.","sk":"Počkaj chvíľu, ešte dojedám."},"topic":"table"},{"id":"family-table-018","prompt":{"es":"No puedo con el postre.","sk":"Dezert už nezvládnem."},"reply":{"es":"Te lo llevas y lo tomas mañana.","sk":"Vezmi si ho a daj si ho zajtra."},"topic":"table"},{"id":"family-table-019","prompt":{"es":"¿Cortamos el queso antes de servirlo?","sk":"Nakrájame syr pred podávaním?"},"reply":{"es":"Mejor dejamos que cada uno se corte un trozo.","sk":"Radšej nech si každý odkrojí kúsok."},"topic":"table"},{"id":"family-table-020","prompt":{"es":"Te ha quedado muy jugoso.","sk":"Podarilo sa ti to veľmi šťavnaté."},"reply":{"es":"Lo saqué del horno un poco antes.","sk":"Vybral som to z rúry trochu skôr."},"topic":"table"},{"id":"family-table-021","prompt":{"es":"¿Hay un vaso limpio por ahí?","sk":"Je tam niekde čistý pohár?"},"reply":{"es":"Sí, en el armario de arriba.","sk":"Áno, v hornej skrinke."},"topic":"table"},{"id":"family-table-022","prompt":{"es":"No sabía que te gustaba el picante.","sk":"Nevedel som, že máš rád štipľavé."},"reply":{"es":"Me gusta, pero tampoco demasiado fuerte.","sk":"Mám, ale nie príliš ostré."},"topic":"table"},{"id":"family-table-023","prompt":{"es":"¿Ponemos todo en el centro?","sk":"Dáme všetko do stredu?"},"reply":{"es":"Sí, así cada uno se sirve lo que quiere.","sk":"Áno, tak si každý naberie, čo chce."},"topic":"table"},{"id":"family-table-024","prompt":{"es":"¿Te sabe raro o es cosa mía?","sk":"Chutí ti to zvláštne alebo sa mi to len zdá?"},"reply":{"es":"Tiene un toque de comino, quizá sea eso.","sk":"Je v tom trochu rímskej rasce, možno preto."},"topic":"table"},{"id":"family-table-025","prompt":{"es":"¿Os apetece un café al terminar?","sk":"Dáte si po jedle kávu?"},"reply":{"es":"A mí descafeinado, si tienes.","sk":"Ja bez kofeínu, ak máš."},"topic":"table"},{"id":"family-kitchen-001","prompt":{"es":"¿Por dónde empiezo?","sk":"Čím mám začať?"},"reply":{"es":"Lava los tomates mientras corto la cebolla.","sk":"Umy paradajky, kým nakrájam cibuľu."},"topic":"kitchen"},{"id":"family-kitchen-002","prompt":{"es":"¿Esto va al horno o a la sartén?","sk":"Ide to do rúry alebo na panvicu?"},"reply":{"es":"Primero a la sartén, para que coja color.","sk":"Najprv na panvicu, aby to chytilo farbu."},"topic":"kitchen"},{"id":"family-kitchen-003","prompt":{"es":"No encuentro el pelador.","sk":"Neviem nájsť škrabku."},"reply":{"es":"Mira en el cajón de los cubiertos.","sk":"Pozri do zásuvky s príborom."},"topic":"kitchen"},{"id":"family-kitchen-004","prompt":{"es":"¿Lo corto fino o en trozos grandes?","sk":"Nakrájam to najemno alebo na veľké kusy?"},"reply":{"es":"En trozos pequeños, que se hace antes.","sk":"Na malé kusy, skôr sa to uvarí."},"topic":"kitchen"},{"id":"family-kitchen-005","prompt":{"es":"Se está pegando al fondo.","sk":"Pripaľuje sa to na dne."},"reply":{"es":"Baja el fuego y remueve despacio.","sk":"Stíš plameň a pomaly miešaj."},"topic":"kitchen"},{"id":"family-kitchen-006","prompt":{"es":"¿Cuánto tiempo tiene que reposar?","sk":"Ako dlho to má odpočívať?"},"reply":{"es":"Unos diez minutos, tapado.","sk":"Asi desať minút, prikryté."},"topic":"kitchen"},{"id":"family-kitchen-007","prompt":{"es":"Me falta un huevo para la receta.","sk":"Do receptu mi chýba jedno vajce."},"reply":{"es":"Tengo yo; voy a traértelo.","sk":"Ja mám, idem ti ho priniesť."},"topic":"kitchen"},{"id":"family-kitchen-008","prompt":{"es":"¿Puedo sustituir la mantequilla por aceite?","sk":"Môžem nahradiť maslo olejom?"},"reply":{"es":"Sí, pero pondría un poco menos.","sk":"Áno, ale dal by som ho trochu menej."},"topic":"kitchen"},{"id":"family-kitchen-009","prompt":{"es":"Esto hierve demasiado fuerte.","sk":"Vrie to príliš prudko."},"reply":{"es":"Ponlo a fuego lento.","sk":"Daj to na slabý plameň."},"topic":"kitchen"},{"id":"family-kitchen-010","prompt":{"es":"¿Has probado ya la salsa?","sk":"Už si ochutnal omáčku?"},"reply":{"es":"Todavía no; pásame una cuchara limpia.","sk":"Ešte nie, podaj mi čistú lyžicu."},"topic":"kitchen"},{"id":"family-kitchen-011","prompt":{"es":"Se me ha olvidado comprar levadura.","sk":"Zabudol som kúpiť droždie."},"reply":{"es":"Entonces hacemos otra cosa con la harina.","sk":"Tak z múky spravíme niečo iné."},"topic":"kitchen"},{"id":"family-kitchen-012","prompt":{"es":"¿Te encargas tú de la ensalada?","sk":"Postaráš sa o šalát?"},"reply":{"es":"Sí, y también pongo la mesa.","sk":"Áno, a aj prestriem stôl."},"topic":"kitchen"},{"id":"family-kitchen-013","prompt":{"es":"La masa está demasiado seca.","sk":"Cesto je príliš suché."},"reply":{"es":"Añade agua poco a poco, sin pasarte.","sk":"Pridávaj vodu postupne, neprežeň to."},"topic":"kitchen"},{"id":"family-kitchen-014","prompt":{"es":"¿Esta fuente aguanta el calor?","sk":"Znesie táto misa teplo?"},"reply":{"es":"Sí, es apta para horno.","sk":"Áno, je vhodná do rúry."},"topic":"kitchen"},{"id":"family-kitchen-015","prompt":{"es":"Ya he picado todo.","sk":"Už mám všetko nasekané."},"reply":{"es":"Perfecto, déjalo separado en esos cuencos.","sk":"Výborne, nechaj to oddelene v tých miskách."},"topic":"kitchen"},{"id":"family-kitchen-016","prompt":{"es":"¿Dónde tiramos las cáscaras?","sk":"Kam vyhadzujeme šupky?"},"reply":{"es":"En el cubo pequeño, el de orgánico.","sk":"Do malého koša na bioodpad."},"topic":"kitchen"},{"id":"family-kitchen-017","prompt":{"es":"Me da miedo que quede crudo.","sk":"Bojím sa, aby to nezostalo surové."},"reply":{"es":"Lo comprobamos antes de sacarlo.","sk":"Pred vybratím to skontrolujeme."},"topic":"kitchen"},{"id":"family-kitchen-018","prompt":{"es":"¿Lavamos esto a mano?","sk":"Umyjeme to ručne?"},"reply":{"es":"La tabla sí; los platos van al lavavajillas.","sk":"Dosku áno, taniere idú do umývačky."},"topic":"kitchen"},{"id":"family-kitchen-019","prompt":{"es":"La receta pone una pizca.","sk":"V recepte je napísané štipka."},"reply":{"es":"Pues añade muy poco y luego pruebas.","sk":"Tak pridaj len trošku a potom ochutnaj."},"topic":"kitchen"},{"id":"family-kitchen-020","prompt":{"es":"¿Puedes sujetarme este cuenco?","sk":"Podržíš mi túto misu?"},"reply":{"es":"Sí, avísame cuando empieces a verter.","sk":"Áno, povedz mi, keď začneš nalievať."},"topic":"kitchen"},{"id":"family-kitchen-021","prompt":{"es":"He encendido el horno hace un rato.","sk":"Rúru som zapol pred chvíľou."},"reply":{"es":"Bien, así ya estará caliente.","sk":"Dobre, tak už bude zohriata."},"topic":"kitchen"},{"id":"family-kitchen-022","prompt":{"es":"¿Guardamos el caldo que sobra?","sk":"Odložíme zvyšný vývar?"},"reply":{"es":"Sí, en un recipiente con tapa.","sk":"Áno, do nádoby s vrchnákom."},"topic":"kitchen"},{"id":"family-kitchen-023","prompt":{"es":"El cuchillo no corta nada.","sk":"Ten nôž vôbec nekrája."},"reply":{"es":"Usa el otro; este necesita afilarse.","sk":"Použi druhý, tento treba nabrúsiť."},"topic":"kitchen"},{"id":"family-kitchen-024","prompt":{"es":"¿Le pongo limón ahora?","sk":"Dám tam citrón už teraz?"},"reply":{"es":"Mejor al final, cuando lo sirvamos.","sk":"Radšej nakoniec, keď to budeme podávať."},"topic":"kitchen"},{"id":"family-kitchen-025","prompt":{"es":"Ya está todo recogido.","sk":"Už je všetko upratané."},"reply":{"es":"Entonces siéntate, que te has ganado un descanso.","sk":"Tak si sadni, zaslúžiš si oddych."},"topic":"kitchen"},{"id":"family-home-001","prompt":{"es":"¿Puedes bajar la basura cuando salgas?","sk":"Vynesieš smeti, keď pôjdeš von?"},"reply":{"es":"Sí, déjala junto a la puerta.","sk":"Áno, nechaj ich pri dverách."},"topic":"home"},{"id":"family-home-002","prompt":{"es":"La luz del pasillo se ha fundido.","sk":"Na chodbe sa vypálila žiarovka."},"reply":{"es":"Compro una bombilla esta tarde.","sk":"Popoludní kúpim žiarovku."},"topic":"home"},{"id":"family-home-003","prompt":{"es":"¿Has visto mis llaves por alguna parte?","sk":"Nevidel si niekde moje kľúče?"},"reply":{"es":"Estaban al lado del teléfono.","sk":"Boli vedľa telefónu."},"topic":"home"},{"id":"family-home-004","prompt":{"es":"La lavadora ya ha terminado.","sk":"Práčka už doprala."},"reply":{"es":"Ahora tiendo la ropa.","sk":"Teraz zavesím bielizeň."},"topic":"home"},{"id":"family-home-005","prompt":{"es":"¿Te importa cerrar un poco la persiana?","sk":"Privrieš trochu žalúziu?"},"reply":{"es":"Claro, el sol te está dando de frente.","sk":"Jasné, slnko ti svieti priamo do tváre."},"topic":"home"},{"id":"family-home-006","prompt":{"es":"El grifo sigue goteando.","sk":"Kohútik stále kvapká."},"reply":{"es":"Voy a llamar para que lo miren.","sk":"Zavolám, aby sa naň prišli pozrieť."},"topic":"home"},{"id":"family-home-007","prompt":{"es":"¿Dónde guardamos las sábanas limpias?","sk":"Kam odkladáme čisté plachty?"},"reply":{"es":"En el armario del fondo.","sk":"Do skrine vzadu."},"topic":"home"},{"id":"family-home-008","prompt":{"es":"Hoy me toca limpiar a mí.","sk":"Dnes je upratovanie na mne."},"reply":{"es":"Yo paso la aspiradora, si te ayuda.","sk":"Ak ti to pomôže, ja povysávam."},"topic":"home"},{"id":"family-home-009","prompt":{"es":"¿Puedes hacer menos ruido un momento?","sk":"Môžeš byť chvíľu tichšie?"},"reply":{"es":"Perdona, no sabía que estabas trabajando.","sk":"Prepáč, nevedel som, že pracuješ."},"topic":"home"},{"id":"family-home-010","prompt":{"es":"No queda detergente.","sk":"Došiel prací prostriedok."},"reply":{"es":"Lo apunto en la lista de la compra.","sk":"Pripíšem ho na nákupný zoznam."},"topic":"home"},{"id":"family-home-011","prompt":{"es":"¿Esta ropa ya está seca?","sk":"Je už táto bielizeň suchá?"},"reply":{"es":"Casi; las toallas necesitan un rato más.","sk":"Takmer, uteráky potrebujú ešte chvíľu."},"topic":"home"},{"id":"family-home-012","prompt":{"es":"He movido la mesa para barrer.","sk":"Posunul som stôl, aby som pozametal."},"reply":{"es":"Luego la colocamos entre los dos.","sk":"Potom ho spolu vrátime na miesto."},"topic":"home"},{"id":"family-home-013","prompt":{"es":"¿Me ayudas a cambiar esta funda?","sk":"Pomôžeš mi vymeniť tento poťah?"},"reply":{"es":"Sujeta ese extremo y yo tiro de aquí.","sk":"Podrž ten koniec a ja potiahnem odtiaľto."},"topic":"home"},{"id":"family-home-014","prompt":{"es":"La puerta roza al cerrar.","sk":"Dvere pri zatváraní drhnú."},"reply":{"es":"Sí, lleva unos días así.","sk":"Áno, už pár dní je to tak."},"topic":"home"},{"id":"family-home-015","prompt":{"es":"¿Quién ha regado las plantas?","sk":"Kto polial rastliny?"},"reply":{"es":"Yo, esta mañana; hoy no necesitan más.","sk":"Ja, dnes ráno, dnes už viac netreba."},"topic":"home"},{"id":"family-home-016","prompt":{"es":"Hay que hacer sitio en el armario.","sk":"Treba urobiť miesto v skrini."},"reply":{"es":"Podemos separar lo que ya no usamos.","sk":"Môžeme vytriediť to, čo už nepoužívame."},"topic":"home"},{"id":"family-home-017","prompt":{"es":"¿Dejamos encendida esta lámpara?","sk":"Necháme túto lampu zapnutú?"},"reply":{"es":"Sí, volveré a leer después de cenar.","sk":"Áno, po večeri sa vrátim k čítaniu."},"topic":"home"},{"id":"family-home-018","prompt":{"es":"Se ha ido la luz en la cocina.","sk":"V kuchyni vypadol prúd."},"reply":{"es":"Voy a comprobar si pasa en toda la casa.","sk":"Pozriem sa, či je to v celom byte."},"topic":"home"},{"id":"family-home-019","prompt":{"es":"¿A qué hora viene el técnico?","sk":"O koľkej príde technik?"},"reply":{"es":"Ha dicho que entre las diez y las doce.","sk":"Povedal, že medzi desiatou a dvanástou."},"topic":"home"},{"id":"family-home-020","prompt":{"es":"Ese cajón no cierra bien.","sk":"Tá zásuvka sa zle zatvára."},"reply":{"es":"Hay algo atascado detrás.","sk":"Vzadu je niečo zaseknuté."},"topic":"home"},{"id":"family-home-021","prompt":{"es":"¿Ventilamos antes de salir?","sk":"Vyvetrieme pred odchodom?"},"reply":{"es":"Sí, pero cerremos las ventanas luego.","sk":"Áno, ale potom okná zatvorme."},"topic":"home"},{"id":"family-home-022","prompt":{"es":"Me he encargado de pagar la factura.","sk":"Postaral som sa o zaplatenie účtu."},"reply":{"es":"Gracias, yo reviso la del mes que viene.","sk":"Ďakujem, ja skontrolujem tú budúcomesačnú."},"topic":"home"},{"id":"family-home-023","prompt":{"es":"¿Te dejo espacio en este estante?","sk":"Nechám ti miesto na tejto polici?"},"reply":{"es":"Sí, con la mitad me basta.","sk":"Áno, stačí mi polovica."},"topic":"home"},{"id":"family-home-024","prompt":{"es":"El sofá quedaría mejor junto a la pared.","sk":"Pohovka by lepšie vyzerala pri stene."},"reply":{"es":"Probamos y, si no convence, la movemos.","sk":"Skúsime to a ak sa nám to nebude páčiť, presunieme ju."},"topic":"home"},{"id":"family-home-025","prompt":{"es":"¿Recogemos ahora o después del café?","sk":"Upraceme teraz alebo po káve?"},"reply":{"es":"Lo más grande ahora; el resto puede esperar.","sk":"Veľké veci teraz, zvyšok môže počkať."},"topic":"home"},{"id":"family-plans-001","prompt":{"es":"¿Salimos a dar una vuelta?","sk":"Pôjdeme sa prejsť?"},"reply":{"es":"Sí, pero por una zona con sombra.","sk":"Áno, ale niekam do tieňa."},"topic":"plans"},{"id":"family-plans-002","prompt":{"es":"Me apetece quedarme en casa.","sk":"Mám chuť zostať doma."},"reply":{"es":"Pues buscamos una película y descansamos.","sk":"Tak nájdeme film a oddýchneme si."},"topic":"plans"},{"id":"family-plans-003","prompt":{"es":"¿Qué tal si vamos al mercado?","sk":"Čo keby sme šli na trh?"},"reply":{"es":"Buena idea; hace mucho que no vamos.","sk":"Dobrý nápad, dlho sme tam neboli."},"topic":"plans"},{"id":"family-plans-004","prompt":{"es":"El cine empieza demasiado tarde.","sk":"Kino sa začína príliš neskoro."},"reply":{"es":"Miremos si hay una sesión anterior.","sk":"Pozrime sa, či nie je skoršie predstavenie."},"topic":"plans"},{"id":"family-plans-005","prompt":{"es":"¿Prefieres playa o montaña?","sk":"Máš radšej pláž alebo hory?"},"reply":{"es":"Hoy montaña; necesito cambiar de paisaje.","sk":"Dnes hory, potrebujem zmeniť prostredie."},"topic":"plans"},{"id":"family-plans-006","prompt":{"es":"No hemos reservado nada.","sk":"Nič sme si nerezervovali."},"reply":{"es":"Llamamos antes de ir, por si acaso.","sk":"Pre istotu tam pred odchodom zavoláme."},"topic":"plans"},{"id":"family-plans-007","prompt":{"es":"¿Y si hacemos algo distinto esta vez?","sk":"Čo keby sme tentoraz podnikli niečo iné?"},"reply":{"es":"Propón tú, que yo siempre elijo lo mismo.","sk":"Navrhni ty, ja si vždy vyberiem to isté."},"topic":"plans"},{"id":"family-plans-008","prompt":{"es":"Mañana parece que va a llover.","sk":"Zajtra vraj bude pršať."},"reply":{"es":"Dejamos la excursión para otro día.","sk":"Výlet necháme na inokedy."},"topic":"plans"},{"id":"family-plans-009","prompt":{"es":"¿Nos da tiempo a ver la exposición?","sk":"Stihneme si pozrieť výstavu?"},"reply":{"es":"Si salimos ya, tenemos una hora.","sk":"Ak vyrazíme teraz, máme hodinu."},"topic":"plans"},{"id":"family-plans-010","prompt":{"es":"Ya fui a ese concierto el año pasado.","sk":"Na tom koncerte som bol už vlani."},"reply":{"es":"Entonces busquemos otro que nos apetezca a todos.","sk":"Tak nájdime iný, na ktorý budeme mať chuť všetci."},"topic":"plans"},{"id":"family-plans-011","prompt":{"es":"¿Te apuntas a una partida de cartas?","sk":"Pridáš sa ku kartám?"},"reply":{"es":"Sí, pero tendrás que explicarme las reglas.","sk":"Áno, ale budeš mi musieť vysvetliť pravidlá."},"topic":"plans"},{"id":"family-plans-012","prompt":{"es":"Yo solo puedo por la mañana.","sk":"Môžem len dopoludnia."},"reply":{"es":"Perfecto, quedamos para desayunar.","sk":"Výborne, stretneme sa na raňajkách."},"topic":"plans"},{"id":"family-plans-013","prompt":{"es":"¿Compramos las entradas por internet?","sk":"Kúpime lístky cez internet?"},"reply":{"es":"Sí, así evitamos la cola.","sk":"Áno, vyhneme sa tak rade."},"topic":"plans"},{"id":"family-plans-014","prompt":{"es":"No hace falta organizar cada minuto.","sk":"Nemusíme naplánovať každú minútu."},"reply":{"es":"De acuerdo, dejamos la tarde abierta.","sk":"Súhlasím, popoludnie necháme voľné."},"topic":"plans"},{"id":"family-plans-015","prompt":{"es":"¿A alguien le apetece pasear después?","sk":"Má niekto chuť ísť potom na prechádzku?"},"reply":{"es":"Yo voy, aunque sea un rato.","sk":"Ja pôjdem, hoci len na chvíľu."},"topic":"plans"},{"id":"family-plans-016","prompt":{"es":"Hoy hay demasiada gente en el centro.","sk":"Dnes je v centre priveľa ľudí."},"reply":{"es":"Podemos ir por los barrios de fuera.","sk":"Môžeme ísť do vzdialenejších štvrtí."},"topic":"plans"},{"id":"family-plans-017","prompt":{"es":"¿Lo decidimos sobre la marcha?","sk":"Rozhodneme sa cestou?"},"reply":{"es":"Me parece bien, salvo dónde comer.","sk":"Zdá sa mi to dobré, okrem toho, kde budeme jesť."},"topic":"plans"},{"id":"family-plans-018","prompt":{"es":"Tenemos la tarde libre.","sk":"Máme voľné popoludnie."},"reply":{"es":"Aprovechemos para hacer eso que teníamos pendiente.","sk":"Využime ho na to, čo sme odkladali."},"topic":"plans"},{"id":"family-plans-019","prompt":{"es":"¿Te vendría mejor salir después de las cinco?","sk":"Viac by ti vyhovovalo vyraziť po piatej?"},"reply":{"es":"Mucho mejor, a esa hora ya habré terminado.","sk":"Oveľa viac, vtedy už budem mať hotovo."},"topic":"plans"},{"id":"family-plans-020","prompt":{"es":"La película dura casi tres horas.","sk":"Film trvá takmer tri hodiny."},"reply":{"es":"Pues la vemos un día que no madruguemos.","sk":"Tak si ho pozrieme v deň, keď nebudeme skoro vstávať."},"topic":"plans"},{"id":"family-plans-021","prompt":{"es":"¿Vamos juntos o nos vemos allí?","sk":"Pôjdeme spolu alebo sa stretneme tam?"},"reply":{"es":"Nos vemos allí, yo salgo desde el trabajo.","sk":"Stretneme sa tam, ja pôjdem z práce."},"topic":"plans"},{"id":"family-plans-022","prompt":{"es":"Me da igual el plan, quiero estar con vosotros.","sk":"Na programe mi nezáleží, chcem byť s vami."},"reply":{"es":"Entonces algo sencillo, sin complicarnos.","sk":"Tak niečo jednoduché, bez komplikácií."},"topic":"plans"},{"id":"family-plans-023","prompt":{"es":"¿Dejamos un rato para descansar?","sk":"Necháme si chvíľu na oddych?"},"reply":{"es":"Sí, no hace falta hacerlo todo hoy.","sk":"Áno, nemusíme všetko stihnúť dnes."},"topic":"plans"},{"id":"family-plans-024","prompt":{"es":"Nos han recomendado una ruta nueva.","sk":"Odporučili nám novú trasu."},"reply":{"es":"Miremos cuánto dura antes de decidir.","sk":"Pred rozhodnutím sa pozrime, koľko trvá."},"topic":"plans"},{"id":"family-plans-025","prompt":{"es":"¿Hay que apuntarse antes?","sk":"Treba sa prihlásiť vopred?"},"reply":{"es":"Sí, pero todavía quedan plazas.","sk":"Áno, ale ešte sú voľné miesta."},"topic":"plans"},{"id":"family-errands-001","prompt":{"es":"¿Puedes recoger un paquete por mí?","sk":"Vyzdvihneš za mňa balík?"},"reply":{"es":"Sí, mándame el código de recogida.","sk":"Áno, pošli mi kód na vyzdvihnutie."},"topic":"errands"},{"id":"family-errands-002","prompt":{"es":"Voy a la farmacia, ¿necesitas algo?","sk":"Idem do lekárne, potrebuješ niečo?"},"reply":{"es":"No, gracias; ya he ido esta mañana.","sk":"Nie, ďakujem, už som tam bol dnes ráno."},"topic":"errands"},{"id":"family-errands-003","prompt":{"es":"¿Me llevas hasta la estación?","sk":"Odvezieš ma na stanicu?"},"reply":{"es":"Puedo dejarte allí antes de las nueve.","sk":"Môžem ťa tam zaviezť pred deviatou."},"topic":"errands"},{"id":"family-errands-004","prompt":{"es":"Se me ha olvidado comprar pan.","sk":"Zabudol som kúpiť chlieb."},"reply":{"es":"Paso yo por la panadería.","sk":"Ja sa zastavím v pekárni."},"topic":"errands"},{"id":"family-errands-005","prompt":{"es":"¿Te importa esperar al repartidor?","sk":"Počkáš na kuriéra?"},"reply":{"es":"Sí puedo, pero solo hasta mediodía.","sk":"Môžem, ale len do poludnia."},"topic":"errands"},{"id":"family-errands-006","prompt":{"es":"Tengo que devolver este libro.","sk":"Musím vrátiť túto knihu."},"reply":{"es":"Voy a pasar por la biblioteca; dámelo.","sk":"Pôjdem okolo knižnice, daj mi ju."},"topic":"errands"},{"id":"family-errands-007","prompt":{"es":"¿Me prestas una bolsa grande?","sk":"Požičiaš mi veľkú tašku?"},"reply":{"es":"Sí, luego déjala en la entrada.","sk":"Áno, potom ju nechaj pri vchode."},"topic":"errands"},{"id":"family-errands-008","prompt":{"es":"No llego a la cita si voy andando.","sk":"Ak pôjdem pešo, nestihnem dohodnutý termín."},"reply":{"es":"Te acompaño en coche.","sk":"Odveziem ťa autom."},"topic":"errands"},{"id":"family-errands-009","prompt":{"es":"¿Puedes comprobar si queda leche?","sk":"Pozrieš sa, či máme ešte mlieko?"},"reply":{"es":"Queda medio cartón.","sk":"Zostala polovica balenia."},"topic":"errands"},{"id":"family-errands-010","prompt":{"es":"He comprado lo de tu lista.","sk":"Kúpil som to z tvojho zoznamu."},"reply":{"es":"Gracias; dime cuánto te debo.","sk":"Ďakujem, povedz, koľko ti dlhujem."},"topic":"errands"},{"id":"family-errands-011","prompt":{"es":"¿Te viene mal llevar esta caja?","sk":"Nevyhovuje ti odniesť túto škatuľu?"},"reply":{"es":"Ahora no puedo, pero luego sí.","sk":"Teraz nemôžem, ale neskôr áno."},"topic":"errands"},{"id":"family-errands-012","prompt":{"es":"Mañana viene alguien a revisar el gas.","sk":"Zajtra príde niekto skontrolovať plyn."},"reply":{"es":"Me quedo yo en casa por la mañana.","sk":"Ja zostanem dopoludnia doma."},"topic":"errands"},{"id":"family-errands-013","prompt":{"es":"¿Pasas cerca de correos?","sk":"Ideš okolo pošty?"},"reply":{"es":"Sí, ¿quieres que eche esa carta?","sk":"Áno, chceš, aby som odoslal ten list?"},"topic":"errands"},{"id":"family-errands-014","prompt":{"es":"Necesito imprimir dos páginas.","sk":"Potrebujem vytlačiť dve strany."},"reply":{"es":"Envíamelas y las imprimo aquí.","sk":"Pošli mi ich a vytlačím ich tu."},"topic":"errands"},{"id":"family-errands-015","prompt":{"es":"¿Puedes traer cambio de diez euros?","sk":"Prinesieš drobné z desiatich eur?"},"reply":{"es":"Lo intento, pero no sé si tendrán.","sk":"Skúsim to, ale neviem, či budú mať."},"topic":"errands"},{"id":"family-errands-016","prompt":{"es":"Hoy no puedo hacerte ese favor.","sk":"Dnes ti tú láskavosť nemôžem urobiť."},"reply":{"es":"Lo entiendo; buscaré otra solución.","sk":"Rozumiem, nájdem iné riešenie."},"topic":"errands"},{"id":"family-errands-017","prompt":{"es":"¿Me sujetas la puerta un segundo?","sk":"Podržíš mi na sekundu dvere?"},"reply":{"es":"Claro, pasa primero.","sk":"Jasné, prejdi prvý."},"topic":"errands"},{"id":"family-errands-018","prompt":{"es":"Se me ha quedado el móvil sin batería.","sk":"Vybil sa mi mobil."},"reply":{"es":"Te dejo el mío para llamar.","sk":"Požičiam ti svoj, aby si zavolal."},"topic":"errands"},{"id":"family-errands-019","prompt":{"es":"¿Necesitas que te acompañe al banco?","sk":"Potrebuješ, aby som šiel s tebou do banky?"},"reply":{"es":"No hace falta, pero gracias por ofrecerte.","sk":"Netreba, ale ďakujem za ponuku."},"topic":"errands"},{"id":"family-errands-020","prompt":{"es":"Voy a devolver este abrigo.","sk":"Idem vrátiť tento kabát."},"reply":{"es":"Acuérdate de llevar el recibo.","sk":"Nezabudni si vziať účtenku."},"topic":"errands"},{"id":"family-errands-021","prompt":{"es":"¿Te acerco algo del supermercado?","sk":"Prinesiem ti niečo zo supermarketu?"},"reply":{"es":"Unos limones, si no te importa.","sk":"Ak ti to nevadí, zopár citrónov."},"topic":"errands"},{"id":"family-errands-022","prompt":{"es":"Me han cambiado la hora del trámite.","sk":"Zmenili mi čas vybavovania na úrade."},"reply":{"es":"Entonces ajustamos la salida.","sk":"Tak prispôsobíme odchod."},"topic":"errands"},{"id":"family-errands-023","prompt":{"es":"¿Puedes mirar el buzón al bajar?","sk":"Pozrieš schránku, keď pôjdeš dole?"},"reply":{"es":"Sí, hace días que no la abro.","sk":"Áno, už pár dní som ju neotvoril."},"topic":"errands"},{"id":"family-errands-024","prompt":{"es":"Tengo tus documentos preparados.","sk":"Mám pripravené tvoje doklady."},"reply":{"es":"Paso a por ellos esta tarde.","sk":"Popoludní sa po ne zastavím."},"topic":"errands"},{"id":"family-errands-025","prompt":{"es":"¿Te debo algo por la compra?","sk":"Dlhujem ti niečo za nákup?"},"reply":{"es":"Sí, te paso el importe luego.","sk":"Áno, sumu ti pošlem neskôr."},"topic":"errands"},{"id":"family-news-001","prompt":{"es":"¿Qué tal te ha ido la semana?","sk":"Ako sa ti darilo tento týždeň?"},"reply":{"es":"Movida, pero he terminado lo más importante.","sk":"Bola rušná, ale to najdôležitejšie mám hotové."},"topic":"news"},{"id":"family-news-002","prompt":{"es":"Al final han aceptado mi propuesta.","sk":"Nakoniec prijali môj návrh."},"reply":{"es":"¡Qué bien! ¿Cuándo empezáis?","sk":"To je výborné! Kedy začínate?"},"topic":"news"},{"id":"family-news-003","prompt":{"es":"¿Se sabe algo de la mudanza?","sk":"Vie sa už niečo o sťahovaní?"},"reply":{"es":"Todavía no tenemos fecha.","sk":"Ešte nemáme dátum."},"topic":"news"},{"id":"family-news-004","prompt":{"es":"Hoy he hablado con Pablo.","sk":"Dnes som hovoril s Pablom."},"reply":{"es":"¿Y cómo le van las cosas?","sk":"A ako sa mu darí?"},"topic":"news"},{"id":"family-news-005","prompt":{"es":"¿Sigues con el mismo proyecto?","sk":"Stále pracuješ na tom istom projekte?"},"reply":{"es":"Sí, aunque ahora hago otra parte.","sk":"Áno, hoci teraz robím inú časť."},"topic":"news"},{"id":"family-news-006","prompt":{"es":"Nos han cambiado el horario otra vez.","sk":"Zase nám zmenili rozvrh."},"reply":{"es":"Vaya, ¿te viene peor que antes?","sk":"To je nepríjemné, vyhovuje ti menej než predtým?"},"topic":"news"},{"id":"family-news-007","prompt":{"es":"¿Qué fue de aquel curso que querías hacer?","sk":"Ako to dopadlo s tým kurzom, na ktorý si chcel ísť?"},"reply":{"es":"Me apunté y empiezo el mes que viene.","sk":"Prihlásil som sa a začínam budúci mesiac."},"topic":"news"},{"id":"family-news-008","prompt":{"es":"No te he contado lo del viaje.","sk":"Ešte som ti nepovedal o tej ceste."},"reply":{"es":"Cuéntame, ¿al final pudisteis ir?","sk":"Porozprávaj, nakoniec ste mohli ísť?"},"topic":"news"},{"id":"family-news-009","prompt":{"es":"¿Has tenido noticias de Inés?","sk":"Ozvala sa ti Inés?"},"reply":{"es":"Sí, me ha mandado unas fotos.","sk":"Áno, poslala mi fotky."},"topic":"news"},{"id":"family-news-010","prompt":{"es":"La entrevista salió mejor de lo que esperaba.","sk":"Pohovor vyšiel lepšie, než som čakal."},"reply":{"es":"Me alegro; ya me dirás cuando te contesten.","sk":"Teším sa, povedz mi, keď ti odpovedia."},"topic":"news"},{"id":"family-news-011","prompt":{"es":"¿Cómo acabó lo del coche?","sk":"Ako dopadla tá vec s autom?"},"reply":{"es":"Era una avería pequeña, por suerte.","sk":"Našťastie to bola drobná porucha."},"topic":"news"},{"id":"family-news-012","prompt":{"es":"Estamos pensando en cambiar de barrio.","sk":"Uvažujeme, že sa presťahujeme do inej štvrte."},"reply":{"es":"¿Por el trabajo o por otra cosa?","sk":"Kvôli práci alebo pre niečo iné?"},"topic":"news"},{"id":"family-news-013","prompt":{"es":"¿Qué tienes entre manos ahora?","sk":"Na čom teraz pracuješ?"},"reply":{"es":"Estoy preparando una charla corta.","sk":"Pripravujem krátku prednášku."},"topic":"news"},{"id":"family-news-014","prompt":{"es":"Esta mañana me he llevado una sorpresa.","sk":"Dnes ráno ma niečo prekvapilo."},"reply":{"es":"Por tu cara, parece que ha sido buena.","sk":"Podľa tvojej tváre to vyzerá na dobré prekvapenie."},"topic":"news"},{"id":"family-news-015","prompt":{"es":"¿Lo de la exposición sigue en pie?","sk":"Platí ešte tá výstava?"},"reply":{"es":"Sí, la inauguración es el viernes.","sk":"Áno, otvorenie je v piatok."},"topic":"news"},{"id":"family-news-016","prompt":{"es":"Me han dicho que vais a venir más a menudo.","sk":"Počul som, že budete chodiť častejšie."},"reply":{"es":"Esa es la idea, pero aún no está cerrado.","sk":"To je plán, ale ešte to nie je isté."},"topic":"news"},{"id":"family-news-017","prompt":{"es":"¿Has resuelto el problema del ordenador?","sk":"Vyriešil si problém s počítačom?"},"reply":{"es":"Sí, bastaba con actualizarlo.","sk":"Áno, stačilo ho aktualizovať."},"topic":"news"},{"id":"family-news-018","prompt":{"es":"Por fin he encontrado el libro que buscaba.","sk":"Konečne som našiel knihu, ktorú som hľadal."},"reply":{"es":"¿Era la edición que querías?","sk":"Bolo to to vydanie, ktoré si chcel?"},"topic":"news"},{"id":"family-news-019","prompt":{"es":"¿En qué ha quedado la reunión?","sk":"Na čom sa dohodli na porade?"},"reply":{"es":"Han decidido esperar una semana.","sk":"Rozhodli sa týždeň počkať."},"topic":"news"},{"id":"family-news-020","prompt":{"es":"No hay grandes novedades por aquí.","sk":"Tu nie sú žiadne veľké novinky."},"reply":{"es":"A veces eso también es una buena noticia.","sk":"Niekedy je aj to dobrá správa."},"topic":"news"},{"id":"family-news-021","prompt":{"es":"¿Te han confirmado ya la reserva?","sk":"Už ti potvrdili rezerváciu?"},"reply":{"es":"Sí, tengo el correo guardado.","sk":"Áno, mám uložený e-mail."},"topic":"news"},{"id":"family-news-022","prompt":{"es":"Llevaba tiempo queriendo contártelo.","sk":"Už dlho som ti to chcel povedať."},"reply":{"es":"Pues te escucho, sin prisas.","sk":"Tak počúvam, neponáhľaj sa."},"topic":"news"},{"id":"family-news-023","prompt":{"es":"¿Cómo va esa afición nueva?","sk":"Ako pokračuje tvoj nový koníček?"},"reply":{"es":"Me cuesta, pero cada vez me gusta más.","sk":"Ide mi to ťažko, ale baví ma čoraz viac."},"topic":"news"},{"id":"family-news-024","prompt":{"es":"Hemos tenido que retrasar la obra.","sk":"Museli sme odložiť rekonštrukciu."},"reply":{"es":"¿Mucho tiempo o solo unos días?","sk":"Na dlho alebo len o pár dní?"},"topic":"news"},{"id":"family-news-025","prompt":{"es":"¿Y tú? Siempre acabamos hablando de mí.","sk":"A ty? Vždy nakoniec hovoríme o mne."},"reply":{"es":"Pues también tengo algo que contarte.","sk":"Aj ja ti mám čo povedať."},"topic":"news"},{"id":"family-wellbeing-001","prompt":{"es":"¿Has dormido bien esta noche?","sk":"Spal si dnes v noci dobre?"},"reply":{"es":"Me he despertado pronto, pero he descansado.","sk":"Zobudil som sa skoro, ale oddýchol som si."},"topic":"wellbeing"},{"id":"family-wellbeing-002","prompt":{"es":"Te noto más callado de lo normal.","sk":"Zdáš sa mi tichší než zvyčajne."},"reply":{"es":"Estoy cansado, no es por nada contigo.","sk":"Som unavený, s tebou to nesúvisí."},"topic":"wellbeing"},{"id":"family-wellbeing-003","prompt":{"es":"¿Te apetece hablar de lo que ha pasado?","sk":"Chceš hovoriť o tom, čo sa stalo?"},"reply":{"es":"Ahora no, quizá después de comer.","sk":"Teraz nie, možno po obede."},"topic":"wellbeing"},{"id":"family-wellbeing-004","prompt":{"es":"Hoy tengo la cabeza en otra parte.","sk":"Dnes som myšlienkami inde."},"reply":{"es":"No pasa nada, repetimos esto luego.","sk":"Nevadí, zopakujeme si to neskôr."},"topic":"wellbeing"},{"id":"family-wellbeing-005","prompt":{"es":"¿Estás cómodo en esa silla?","sk":"Sedí sa ti pohodlne na tej stoličke?"},"reply":{"es":"Con un cojín estaría mejor.","sk":"S vankúšom by to bolo lepšie."},"topic":"wellbeing"},{"id":"family-wellbeing-006","prompt":{"es":"Me vendría bien un poco de aire.","sk":"Prospelo by mi trochu vzduchu."},"reply":{"es":"Salimos al balcón un momento.","sk":"Vyjdeme na chvíľu na balkón."},"topic":"wellbeing"},{"id":"family-wellbeing-007","prompt":{"es":"¿Quieres descansar antes de salir?","sk":"Chceš si pred odchodom oddýchnuť?"},"reply":{"es":"Sí, dame veinte minutos.","sk":"Áno, daj mi dvadsať minút."},"topic":"wellbeing"},{"id":"family-wellbeing-008","prompt":{"es":"Esta semana se me ha hecho larga.","sk":"Tento týždeň mi pripadal dlhý."},"reply":{"es":"Pues hoy vamos a tomárnoslo con calma.","sk":"Tak si to dnes užijeme v pokoji."},"topic":"wellbeing"},{"id":"family-wellbeing-009","prompt":{"es":"¿Te molesta el ruido de la tele?","sk":"Ruší ťa zvuk televízora?"},"reply":{"es":"Un poco; ¿podemos bajarlo?","sk":"Trochu, môžeme ho stíšiť?"},"topic":"wellbeing"},{"id":"family-wellbeing-010","prompt":{"es":"No estoy de humor para bromas.","sk":"Nemám náladu na žarty."},"reply":{"es":"Entendido, lo dejamos.","sk":"Rozumiem, necháme to tak."},"topic":"wellbeing"},{"id":"family-wellbeing-011","prompt":{"es":"¿Te encuentras con fuerzas para el paseo?","sk":"Máš dosť síl na prechádzku?"},"reply":{"es":"Sí, si vamos despacio.","sk":"Áno, ak pôjdeme pomaly."},"topic":"wellbeing"},{"id":"family-wellbeing-012","prompt":{"es":"Necesito desconectar un rato.","sk":"Potrebujem na chvíľu vypnúť."},"reply":{"es":"Te dejo tranquilo; luego hablamos.","sk":"Nechám ťa v pokoji, potom sa porozprávame."},"topic":"wellbeing"},{"id":"family-wellbeing-013","prompt":{"es":"¿Te ha sentado bien la comida?","sk":"Sadlo ti jedlo dobre?"},"reply":{"es":"Sí, pero he comido demasiado.","sk":"Áno, ale zjedol som priveľa."},"topic":"wellbeing"},{"id":"family-wellbeing-014","prompt":{"es":"Hoy estoy mucho más animada.","sk":"Dnes mám oveľa lepšiu náladu."},"reply":{"es":"Se te nota, me alegro.","sk":"Vidno to na tebe, teším sa."},"topic":"wellbeing"},{"id":"family-wellbeing-015","prompt":{"es":"¿Quieres que paremos un momento?","sk":"Chceš, aby sme sa na chvíľu zastavili?"},"reply":{"es":"Sí, necesito sentarme.","sk":"Áno, potrebujem si sadnúť."},"topic":"wellbeing"},{"id":"family-wellbeing-016","prompt":{"es":"Me preocupa no llegar a todo.","sk":"Trápi ma, že všetko nestíham."},"reply":{"es":"Veamos qué puede esperar.","sk":"Pozrime sa, čo môže počkať."},"topic":"wellbeing"},{"id":"family-wellbeing-017","prompt":{"es":"¿Hay algo que pueda hacer por ti hoy?","sk":"Môžem dnes pre teba niečo urobiť?"},"reply":{"es":"Solo acompañarme un rato.","sk":"Len mi chvíľu robiť spoločnosť."},"topic":"wellbeing"},{"id":"family-wellbeing-018","prompt":{"es":"Últimamente me cuesta concentrarme.","sk":"V poslednom čase sa ťažko sústredím."},"reply":{"es":"Podemos hablar de una cosa cada vez.","sk":"Môžeme preberať veci po jednej."},"topic":"wellbeing"},{"id":"family-wellbeing-019","prompt":{"es":"¿Has tenido un día tranquilo?","sk":"Mal si pokojný deň?"},"reply":{"es":"Al principio sí; luego se complicó.","sk":"Spočiatku áno, potom sa to skomplikovalo."},"topic":"wellbeing"},{"id":"family-wellbeing-020","prompt":{"es":"Me siento mejor después de contártelo.","sk":"Po tom, čo som ti to povedal, sa cítim lepšie."},"reply":{"es":"Gracias por confiar en mí.","sk":"Ďakujem, že mi dôveruješ."},"topic":"wellbeing"},{"id":"family-wellbeing-021","prompt":{"es":"¿Te apetece compañía o prefieres estar solo?","sk":"Chceš spoločnosť alebo radšej byť sám?"},"reply":{"es":"Un poco de compañía me vendrá bien.","sk":"Trochu spoločnosti mi prospeje."},"topic":"wellbeing"},{"id":"family-wellbeing-022","prompt":{"es":"Hoy no me sale nada a la primera.","sk":"Dnes mi nič nejde na prvý pokus."},"reply":{"es":"No tenemos prisa, probamos otra vez.","sk":"Neponáhľame sa, skúsime to znovu."},"topic":"wellbeing"},{"id":"family-wellbeing-023","prompt":{"es":"¿El viaje se te ha hecho pesado?","sk":"Bola pre teba cesta únavná?"},"reply":{"es":"La última hora sí, pero ya estoy bien.","sk":"Posledná hodina áno, ale už som v poriadku."},"topic":"wellbeing"},{"id":"family-wellbeing-024","prompt":{"es":"Tengo ganas de volver a mi rutina.","sk":"Chcem sa vrátiť k svojmu bežnému režimu."},"reply":{"es":"Mañana podemos empezar por algo sencillo.","sk":"Zajtra môžeme začať niečím jednoduchým."},"topic":"wellbeing"},{"id":"family-wellbeing-025","prompt":{"es":"¿Qué te ayudaría a estar más a gusto?","sk":"Čo by ti pomohlo cítiť sa príjemnejšie?"},"reply":{"es":"Que bajáramos un poco el ritmo.","sk":"Keby sme trochu spomalili."},"topic":"wellbeing"},{"id":"family-support-001","prompt":{"es":"No sé por dónde empezar con este lío.","sk":"Neviem, kde s týmto zmätkom začať."},"reply":{"es":"Si quieres, hacemos una lista juntos.","sk":"Ak chceš, spolu si spravíme zoznam."},"topic":"support"},{"id":"family-support-002","prompt":{"es":"¿Crees que me he equivocado?","sk":"Myslíš, že som urobil chybu?"},"reply":{"es":"No conozco todos los detalles; cuéntame un poco más.","sk":"Nepoznám všetky podrobnosti, povedz mi viac."},"topic":"support"},{"id":"family-support-003","prompt":{"es":"Me da vergüenza pedir ayuda.","sk":"Hanbím sa požiadať o pomoc."},"reply":{"es":"A mí no me molesta que me la pidas.","sk":"Mne neprekáža, keď ma o ňu požiadaš."},"topic":"support"},{"id":"family-support-004","prompt":{"es":"¿Tú qué harías en mi lugar?","sk":"Čo by si robil na mojom mieste?"},"reply":{"es":"Primero intentaría aclarar qué es lo más urgente.","sk":"Najprv by som si ujasnil, čo najviac súri."},"topic":"support"},{"id":"family-support-005","prompt":{"es":"Al final me he atrevido a decirlo.","sk":"Nakoniec som sa to odvážil povedať."},"reply":{"es":"Sé que te costaba; ¿cómo te has quedado?","sk":"Viem, že to bolo ťažké, ako sa teraz cítiš?"},"topic":"support"},{"id":"family-support-006","prompt":{"es":"¿Puedes escucharme sin interrumpir?","sk":"Môžeš ma vypočuť bez prerušovania?"},"reply":{"es":"Sí, termina y después te digo.","sk":"Áno, dopovedz a potom sa vyjadrím."},"topic":"support"},{"id":"family-support-007","prompt":{"es":"Tengo miedo de decepcionarles.","sk":"Bojím sa, že ich sklamem."},"reply":{"es":"Lo entiendo; también cuenta lo que tú necesitas.","sk":"Rozumiem, dôležité je aj to, čo potrebuješ ty."},"topic":"support"},{"id":"family-support-008","prompt":{"es":"¿Te parece exagerado que me afecte tanto?","sk":"Zdá sa ti prehnané, že ma to tak zasahuje?"},"reply":{"es":"No voy a decirte cómo deberías sentirte.","sk":"Nebudem ti hovoriť, ako by si sa mal cítiť."},"topic":"support"},{"id":"family-support-009","prompt":{"es":"No necesito una solución ahora.","sk":"Teraz nepotrebujem riešenie."},"reply":{"es":"Vale, te escucho y ya está.","sk":"Dobre, len ťa vypočujem."},"topic":"support"},{"id":"family-support-010","prompt":{"es":"¿Me ayudas a preparar lo que voy a decir?","sk":"Pomôžeš mi pripraviť, čo poviem?"},"reply":{"es":"Claro, ensayamos las primeras frases.","sk":"Jasné, nacvičíme prvé vety."},"topic":"support"},{"id":"family-support-011","prompt":{"es":"Me ha salido fatal la presentación.","sk":"Prezentácia sa mi vôbec nepodarila."},"reply":{"es":"¿Qué parte salió mal y cuál sí funcionó?","sk":"Ktorá časť nevyšla a ktorá fungovala?"},"topic":"support"},{"id":"family-support-012","prompt":{"es":"¿Podemos hablar de otra cosa un rato?","sk":"Môžeme chvíľu hovoriť o niečom inom?"},"reply":{"es":"Por supuesto; no tienes que seguir ahora.","sk":"Samozrejme, teraz nemusíš pokračovať."},"topic":"support"},{"id":"family-support-013","prompt":{"es":"Siento que no avanzo nada.","sk":"Mám pocit, že sa vôbec neposúvam."},"reply":{"es":"Hace un mes esto te costaba mucho más.","sk":"Pred mesiacom ti toto išlo oveľa ťažšie."},"topic":"support"},{"id":"family-support-014","prompt":{"es":"¿Te quedas conmigo hasta que llamen?","sk":"Zostaneš so mnou, kým zavolajú?"},"reply":{"es":"Sí, no tengo que irme todavía.","sk":"Áno, ešte nemusím odísť."},"topic":"support"},{"id":"family-support-015","prompt":{"es":"Me cuesta admitir que no puedo solo.","sk":"Ťažko priznávam, že to sám nezvládnem."},"reply":{"es":"Podemos repartirlo sin que pierdas el control.","sk":"Môžeme si to rozdeliť tak, aby si mal veci pod kontrolou."},"topic":"support"},{"id":"family-support-016","prompt":{"es":"¿Quieres que te dé mi opinión?","sk":"Chceš počuť môj názor?"},"reply":{"es":"Sí, pero dímelo con calma.","sk":"Áno, ale povedz mi ho pokojne."},"topic":"support"},{"id":"family-support-017","prompt":{"es":"No me esperaba esa respuesta.","sk":"Takú odpoveď som nečakal."},"reply":{"es":"Normal que necesites tiempo para pensarla.","sk":"Je pochopiteľné, že potrebuješ čas o nej premýšľať."},"topic":"support"},{"id":"family-support-018","prompt":{"es":"¿Y si vuelvo a fallar?","sk":"A čo ak znovu zlyhám?"},"reply":{"es":"Entonces miramos qué cambiar para la próxima.","sk":"Tak sa pozrieme, čo nabudúce zmeniť."},"topic":"support"},{"id":"family-support-019","prompt":{"es":"Gracias por no quitarle importancia.","sk":"Ďakujem, že to nezľahčuješ."},"reply":{"es":"Si a ti te importa, merece que lo escuche.","sk":"Ak je to pre teba dôležité, stojí to za vypočutie."},"topic":"support"},{"id":"family-support-020","prompt":{"es":"¿Puedo contarte algo que me preocupa?","sk":"Môžem ti povedať niečo, čo ma trápi?"},"reply":{"es":"Sí, y si ahora no sé qué decir, te lo diré.","sk":"Áno, a ak nebudem vedieť odpovedať, poviem ti to."},"topic":"support"},{"id":"family-support-021","prompt":{"es":"Estoy harto de darle vueltas.","sk":"Mám dosť toho, že nad tým stále premýšľam."},"reply":{"es":"Hagamos una pausa y lo retomamos luego.","sk":"Dajme si prestávku a vráťme sa k tomu neskôr."},"topic":"support"},{"id":"family-support-022","prompt":{"es":"¿Me acompañarías a hablar con ellos?","sk":"Šiel by si so mnou porozprávať sa s nimi?"},"reply":{"es":"Sí, pero deja claro qué papel quieres que tenga.","sk":"Áno, ale povedz jasne, akú úlohu mám mať."},"topic":"support"},{"id":"family-support-023","prompt":{"es":"Lo he conseguido después de muchos intentos.","sk":"Po mnohých pokusoch sa mi to podarilo."},"reply":{"es":"Eso tiene mucho mérito.","sk":"To si zaslúži uznanie."},"topic":"support"},{"id":"family-support-024","prompt":{"es":"¿Te importa recordármelo mañana?","sk":"Pripomenieš mi to zajtra?"},"reply":{"es":"Sí, te escribo por la mañana.","sk":"Áno, ráno ti napíšem."},"topic":"support"},{"id":"family-support-025","prompt":{"es":"Hoy solo necesito que estés aquí.","sk":"Dnes potrebujem len to, aby si tu bol."},"reply":{"es":"Aquí estoy, no hace falta hablar.","sk":"Som tu, nemusíme hovoriť."},"topic":"support"},{"id":"family-boundaries-001","prompt":{"es":"¿Podemos quedarnos toda la semana?","sk":"Môžeme zostať celý týždeň?"},"reply":{"es":"Esta vez solo podemos recibiros hasta el lunes.","sk":"Tentoraz vás môžeme ubytovať len do pondelka."},"topic":"boundaries"},{"id":"family-boundaries-002","prompt":{"es":"No quiero que publiques esa foto.","sk":"Nechcem, aby si zverejnil tú fotku."},"reply":{"es":"De acuerdo, no la comparto.","sk":"Dobre, nebudem ju zdieľať."},"topic":"boundaries"},{"id":"family-boundaries-003","prompt":{"es":"¿Te molesta que te pregunte por eso?","sk":"Prekáža ti, že sa ťa na to pýtam?"},"reply":{"es":"Prefiero no hablarlo delante de todos.","sk":"Radšej o tom nechcem hovoriť pred všetkými."},"topic":"boundaries"},{"id":"family-boundaries-004","prompt":{"es":"Hoy necesito terminar a mi hora.","sk":"Dnes potrebujem skončiť načas."},"reply":{"es":"Lo respeto; seguimos otro día.","sk":"Rešpektujem to, budeme pokračovať inokedy."},"topic":"boundaries"},{"id":"family-boundaries-005","prompt":{"es":"¿Me das tu contraseña para entrar?","sk":"Dáš mi svoje heslo, aby som sa prihlásil?"},"reply":{"es":"Prefiero escribirla yo sin compartirla.","sk":"Radšej ho zadám sám bez zdieľania."},"topic":"boundaries"},{"id":"family-boundaries-006","prompt":{"es":"No me avises con tan poco tiempo.","sk":"Nedávaj mi vedieť tak neskoro."},"reply":{"es":"Tienes razón, la próxima te aviso antes.","sk":"Máš pravdu, nabudúce ti dám vedieť skôr."},"topic":"boundaries"},{"id":"family-boundaries-007","prompt":{"es":"¿Puedes encargarte de esto todos los viernes?","sk":"Môžeš sa o to starať každý piatok?"},"reply":{"es":"Alguno sí, pero no puedo comprometerme a todos.","sk":"Niektorý áno, ale na každý sa zaviazať nemôžem."},"topic":"boundaries"},{"id":"family-boundaries-008","prompt":{"es":"Esa broma no me hace gracia.","sk":"Ten vtip mi nepripadá smiešny."},"reply":{"es":"Entendido, no lo repito.","sk":"Rozumiem, nebudem ho opakovať."},"topic":"boundaries"},{"id":"family-boundaries-009","prompt":{"es":"¿Por qué no me contestaste anoche?","sk":"Prečo si mi včera večer neodpovedal?"},"reply":{"es":"A partir de cierta hora desconecto el móvil.","sk":"Od určitej hodiny vypínam mobil."},"topic":"boundaries"},{"id":"family-boundaries-010","prompt":{"es":"Quiero decidir esto por mi cuenta.","sk":"Chcem sa v tomto rozhodnúť sám."},"reply":{"es":"Vale, si luego quieres hablar, aquí estoy.","sk":"Dobre, ak sa potom budeš chcieť porozprávať, som tu."},"topic":"boundaries"},{"id":"family-boundaries-011","prompt":{"es":"¿Te vienes aunque estés cansado?","sk":"Prídeš, aj keď si unavený?"},"reply":{"es":"Hoy voy a descansar; nos vemos mañana.","sk":"Dnes si oddýchnem, uvidíme sa zajtra."},"topic":"boundaries"},{"id":"family-boundaries-012","prompt":{"es":"Prefiero que llames antes de pasar.","sk":"Radšej chcem, aby si pred návštevou zavolal."},"reply":{"es":"Hecho, no volveré a aparecer sin avisar.","sk":"Dohodnuté, už neprídem bez ohlásenia."},"topic":"boundaries"},{"id":"family-boundaries-013","prompt":{"es":"¿Nos puedes prestar más dinero?","sk":"Môžeš nám požičať viac peňazí?"},"reply":{"es":"Ahora no puedo prestar más.","sk":"Teraz už viac požičať nemôžem."},"topic":"boundaries"},{"id":"family-boundaries-014","prompt":{"es":"No quiero ser yo quien se lo diga.","sk":"Nechcem byť ten, kto mu to povie."},"reply":{"es":"Lo entiendo; hablaré directamente con él.","sk":"Rozumiem, porozprávam sa priamo s ním."},"topic":"boundaries"},{"id":"family-boundaries-015","prompt":{"es":"¿Podemos usar tu habitación para guardar cajas?","sk":"Môžeme v tvojej izbe skladovať škatule?"},"reply":{"es":"Solo hasta el domingo; después necesito el espacio.","sk":"Len do nedele, potom potrebujem miesto."},"topic":"boundaries"},{"id":"family-boundaries-016","prompt":{"es":"Me gustaría acabar la frase.","sk":"Rád by som dopovedal vetu."},"reply":{"es":"Perdona, sigue.","sk":"Prepáč, pokračuj."},"topic":"boundaries"},{"id":"family-boundaries-017","prompt":{"es":"¿Te enfadas si esta vez no voy?","sk":"Nahneváš sa, ak tentoraz neprídem?"},"reply":{"es":"No, gracias por decírmelo claramente.","sk":"Nie, ďakujem, že mi to hovoríš jasne."},"topic":"boundaries"},{"id":"family-boundaries-018","prompt":{"es":"No voy a discutir esto por mensajes.","sk":"Nebudem sa o tom hádať cez správy."},"reply":{"es":"Entonces buscamos un momento para hablar.","sk":"Tak nájdime chvíľu na rozhovor."},"topic":"boundaries"},{"id":"family-boundaries-019","prompt":{"es":"¿Puedo contarle lo que me has dicho?","sk":"Môžem mu povedať to, čo si mi povedal?"},"reply":{"es":"Todavía no; prefiero contárselo yo.","sk":"Ešte nie, radšej mu to poviem sám."},"topic":"boundaries"},{"id":"family-boundaries-020","prompt":{"es":"Necesito que respetéis este rato de trabajo.","sk":"Potrebujem, aby ste rešpektovali môj pracovný čas."},"reply":{"es":"Vale, te dejamos terminar.","sk":"Dobre, necháme ťa dokončiť to."},"topic":"boundaries"},{"id":"family-boundaries-021","prompt":{"es":"¿Seguro que no puedes quedarte un poco más?","sk":"Naozaj nemôžeš zostať ešte trochu?"},"reply":{"es":"Me gustaría, pero hoy me tengo que ir.","sk":"Rád by som, ale dnes už musím ísť."},"topic":"boundaries"},{"id":"family-boundaries-022","prompt":{"es":"No me siento cómodo hablando de su vida privada.","sk":"Nie je mi príjemné hovoriť o jeho súkromí."},"reply":{"es":"Tienes razón, cambiemos de tema.","sk":"Máš pravdu, zmeňme tému."},"topic":"boundaries"},{"id":"family-boundaries-023","prompt":{"es":"¿Quieres que decida yo por ti?","sk":"Chceš, aby som rozhodol za teba?"},"reply":{"es":"No, ayúdame a comparar las opciones.","sk":"Nie, pomôž mi porovnať možnosti."},"topic":"boundaries"},{"id":"family-boundaries-024","prompt":{"es":"Esta vez no voy a organizarlo todo.","sk":"Tentoraz nebudem všetko organizovať."},"reply":{"es":"Repartamos las tareas desde el principio.","sk":"Rozdeľme si úlohy hneď na začiatku."},"topic":"boundaries"},{"id":"family-boundaries-025","prompt":{"es":"¿Puedo entrar mientras estás en la llamada?","sk":"Môžem vojsť, keď telefonuješ?"},"reply":{"es":"Espera a que termine y te aviso.","sk":"Počkaj, kým skončím, potom ti dám vedieť."},"topic":"boundaries"},{"id":"family-disagreements-001","prompt":{"es":"Yo no lo veo tan claro.","sk":"Ja to nevidím tak jednoznačne."},"reply":{"es":"¿Qué parte te genera dudas?","sk":"Ktorá časť v tebe vyvoláva pochybnosti?"},"topic":"disagreements"},{"id":"family-disagreements-002","prompt":{"es":"Creo que me has entendido mal.","sk":"Myslím, že si ma zle pochopil."},"reply":{"es":"Puede ser; explícamelo de otra forma.","sk":"Je to možné, vysvetli mi to inak."},"topic":"disagreements"},{"id":"family-disagreements-003","prompt":{"es":"¿Estás diciendo que fue culpa mía?","sk":"Hovoríš, že to bola moja chyba?"},"reply":{"es":"No, digo que podríamos haberlo hablado antes.","sk":"Nie, hovorím, že sme sa o tom mohli porozprávať skôr."},"topic":"disagreements"},{"id":"family-disagreements-004","prompt":{"es":"No estoy de acuerdo con esa decisión.","sk":"S tým rozhodnutím nesúhlasím."},"reply":{"es":"Te escucho; dime qué alternativa propones.","sk":"Počúvam ťa, povedz, akú alternatívu navrhuješ."},"topic":"disagreements"},{"id":"family-disagreements-005","prompt":{"es":"¿Por qué has levantado la voz?","sk":"Prečo si zvýšil hlas?"},"reply":{"es":"Me he alterado; voy a bajar el tono.","sk":"Rozčúlil som sa, budem hovoriť pokojnejšie."},"topic":"disagreements"},{"id":"family-disagreements-006","prompt":{"es":"Eso no era lo que habíamos quedado.","sk":"Takto sme sa nedohodli."},"reply":{"es":"Repasemos lo que entendió cada uno.","sk":"Prejdime si, ako to každý pochopil."},"topic":"disagreements"},{"id":"family-disagreements-007","prompt":{"es":"¿Podemos dejar de hablar todos a la vez?","sk":"Môžeme prestať hovoriť všetci naraz?"},"reply":{"es":"Sí, que termine Ana primero.","sk":"Áno, nech najprv dopovie Ana."},"topic":"disagreements"},{"id":"family-disagreements-008","prompt":{"es":"Me ha dolido cómo lo has dicho.","sk":"Zabolelo ma, ako si to povedal."},"reply":{"es":"Lo siento; podría haberlo expresado mejor.","sk":"Mrzí ma to, mohol som to povedať lepšie."},"topic":"disagreements"},{"id":"family-disagreements-009","prompt":{"es":"¿Lo has hecho a propósito?","sk":"Urobil si to naschvál?"},"reply":{"es":"No, no sabía que te molestaba.","sk":"Nie, nevedel som, že ti to prekáža."},"topic":"disagreements"},{"id":"family-disagreements-010","prompt":{"es":"Estamos mezclando dos problemas distintos.","sk":"Miešame dva rôzne problémy."},"reply":{"es":"Resolvamos uno y luego vamos al otro.","sk":"Vyriešme jeden a potom prejdime na druhý."},"topic":"disagreements"},{"id":"family-disagreements-011","prompt":{"es":"¿De verdad piensas eso de mí?","sk":"Naozaj si to o mne myslíš?"},"reply":{"es":"No hablo de ti en general, sino de esta situación.","sk":"Nehovorím o tebe všeobecne, ale o tejto situácii."},"topic":"disagreements"},{"id":"family-disagreements-012","prompt":{"es":"No hace falta que coincidamos en todo.","sk":"Nemusíme sa zhodovať vo všetkom."},"reply":{"es":"Claro, podemos seguir hablando sin convencernos.","sk":"Jasné, môžeme pokračovať bez toho, aby sme sa presvedčili."},"topic":"disagreements"},{"id":"family-disagreements-013","prompt":{"es":"¿Aceptas que me equivoqué sin querer?","sk":"Prijmeš, že som sa pomýlil nechtiac?"},"reply":{"es":"Sí, ahora veamos cómo arreglarlo.","sk":"Áno, teraz sa pozrime, ako to napraviť."},"topic":"disagreements"},{"id":"family-disagreements-014","prompt":{"es":"He sido injusto contigo.","sk":"Bol som voči tebe nespravodlivý."},"reply":{"es":"Gracias por reconocerlo.","sk":"Ďakujem, že to uznávaš."},"topic":"disagreements"},{"id":"family-disagreements-015","prompt":{"es":"¿Hay algo en lo que sí estemos de acuerdo?","sk":"Je niečo, na čom sa predsa len zhodneme?"},"reply":{"es":"Sí, los dos queremos evitar más líos.","sk":"Áno, obaja sa chceme vyhnúť ďalším problémom."},"topic":"disagreements"},{"id":"family-disagreements-016","prompt":{"es":"Prefiero que no uses siempre ni nunca.","sk":"Radšej nepoužívaj vždy ani nikdy."},"reply":{"es":"Vale, hablemos de lo que pasó ayer.","sk":"Dobre, hovorme o tom, čo sa stalo včera."},"topic":"disagreements"},{"id":"family-disagreements-017","prompt":{"es":"¿Podemos retomarlo cuando estemos más tranquilos?","sk":"Môžeme sa k tomu vrátiť, keď budeme pokojnejší?"},"reply":{"es":"Sí, después de dar un paseo.","sk":"Áno, po prechádzke."},"topic":"disagreements"},{"id":"family-disagreements-018","prompt":{"es":"No era mi intención dejarte fuera.","sk":"Nechcel som ťa vynechať."},"reply":{"es":"Lo sé, pero me habría gustado que me avisaras.","sk":"Viem, ale bol by som rád, keby si mi dal vedieť."},"topic":"disagreements"},{"id":"family-disagreements-019","prompt":{"es":"¿Qué necesitas para que esto quede resuelto?","sk":"Čo potrebuješ, aby sme to mohli uzavrieť?"},"reply":{"es":"Que acordemos cómo hacerlo la próxima vez.","sk":"Aby sme sa dohodli, ako to urobíme nabudúce."},"topic":"disagreements"},{"id":"family-disagreements-020","prompt":{"es":"Ahora entiendo por qué te enfadaste.","sk":"Teraz rozumiem, prečo si sa nahneval."},"reply":{"es":"Me alegro de que hayamos podido hablarlo.","sk":"Som rád, že sme sa o tom mohli porozprávať."},"topic":"disagreements"},{"id":"family-disagreements-021","prompt":{"es":"¿Te parece si empezamos de nuevo?","sk":"Čo povieš na to, keby sme začali odznova?"},"reply":{"es":"Sí, sin sacar asuntos antiguos.","sk":"Áno, bez vyťahovania starých vecí."},"topic":"disagreements"},{"id":"family-disagreements-022","prompt":{"es":"No quería corregirte delante de todos.","sk":"Nechcel som ťa opravovať pred všetkými."},"reply":{"es":"La próxima dímelo aparte.","sk":"Nabudúce mi to povedz bokom."},"topic":"disagreements"},{"id":"family-disagreements-023","prompt":{"es":"¿Hay otra manera de interpretar lo que dijo?","sk":"Dá sa to, čo povedal, pochopiť aj inak?"},"reply":{"es":"Quizá preguntaba de verdad y no estaba criticando.","sk":"Možno sa naozaj pýtal a nekritizoval."},"topic":"disagreements"},{"id":"family-disagreements-024","prompt":{"es":"Seguimos sin estar de acuerdo, pero te entiendo.","sk":"Stále nesúhlasíme, ale rozumiem ti."},"reply":{"es":"Con eso ya hemos avanzado.","sk":"Už tým sme sa posunuli."},"topic":"disagreements"},{"id":"family-disagreements-025","prompt":{"es":"¿Lo dejamos aquí por hoy?","sk":"Necháme to dnes už tak?"},"reply":{"es":"Sí, no vamos a resolver más ahora.","sk":"Áno, teraz už viac nevyriešime."},"topic":"disagreements"},{"id":"family-memories-001","prompt":{"es":"¿Cómo era la calle donde vivías?","sk":"Aká bola ulica, kde si býval?"},"reply":{"es":"Había pocas tiendas y todos nos conocíamos.","sk":"Bolo tam málo obchodov a všetci sme sa poznali."},"topic":"memories"},{"id":"family-memories-002","prompt":{"es":"Me he encontrado esta foto en un cajón.","sk":"Našiel som túto fotku v zásuvke."},"reply":{"es":"Hacía años que no la veía.","sk":"Roky som ju nevidel."},"topic":"memories"},{"id":"family-memories-003","prompt":{"es":"¿Quién te enseñó a montar en bicicleta?","sk":"Kto ťa naučil bicyklovať?"},"reply":{"es":"Mi hermana; tenía mucha paciencia.","sk":"Moja sestra, mala veľkú trpezlivosť."},"topic":"memories"},{"id":"family-memories-004","prompt":{"es":"Yo recuerdo aquella cena de otra manera.","sk":"Na tú večeru si pamätám inak."},"reply":{"es":"Cuéntame tu versión, a ver qué cambia.","sk":"Povedz mi svoju verziu, uvidíme, v čom sa líši."},"topic":"memories"},{"id":"family-memories-005","prompt":{"es":"¿Qué hacíais los domingos antes?","sk":"Čo ste kedysi robievali v nedeľu?"},"reply":{"es":"Solíamos salir a caminar después de comer.","sk":"Po obede sme chodievali na prechádzku."},"topic":"memories"},{"id":"family-memories-006","prompt":{"es":"Ese olor me recuerda a nuestra casa antigua.","sk":"Tá vôňa mi pripomína náš starý dom."},"reply":{"es":"A mí también, sobre todo la cocina.","sk":"Aj mne, najmä kuchyňu."},"topic":"memories"},{"id":"family-memories-007","prompt":{"es":"¿Te acuerdas de la primera vez que viniste?","sk":"Pamätáš si, keď si prišiel prvýkrát?"},"reply":{"es":"Sí, me perdí nada más salir de la estación.","sk":"Áno, zablúdil som hneď po odchode zo stanice."},"topic":"memories"},{"id":"family-memories-008","prompt":{"es":"Antes aquí no había tantos edificios.","sk":"Kedysi tu nebolo toľko budov."},"reply":{"es":"Desde luego, el paisaje ha cambiado mucho.","sk":"To veru nie, krajina sa veľmi zmenila."},"topic":"memories"},{"id":"family-memories-009","prompt":{"es":"¿Qué libro te marcó de joven?","sk":"Ktorá kniha ťa v mladosti silno ovplyvnila?"},"reply":{"es":"Una que leí sin saber nada del autor.","sk":"Jedna, ktorú som čítal bez toho, aby som niečo vedel o autorovi."},"topic":"memories"},{"id":"family-memories-010","prompt":{"es":"Se me ha olvidado el nombre de aquel pueblo.","sk":"Zabudol som meno tej dediny."},"reply":{"es":"Lo tengo apuntado en el diario del viaje.","sk":"Mám ho zapísané v cestovnom denníku."},"topic":"memories"},{"id":"family-memories-011","prompt":{"es":"¿Siempre te ha gustado dibujar?","sk":"Vždy ťa bavilo kreslenie?"},"reply":{"es":"No, empecé bastante más tarde.","sk":"Nie, začal som oveľa neskôr."},"topic":"memories"},{"id":"family-memories-012","prompt":{"es":"Todavía guardo la entrada de ese concierto.","sk":"Stále si odkladám lístok z toho koncertu."},"reply":{"es":"Qué bien; yo perdí la mía.","sk":"To je pekné, ja som svoj stratil."},"topic":"memories"},{"id":"family-memories-013","prompt":{"es":"¿Cómo os comunicabais cuando vivíais lejos?","sk":"Ako ste komunikovali, keď ste bývali ďaleko?"},"reply":{"es":"Nos escribíamos cartas bastante largas.","sk":"Písavali sme si dosť dlhé listy."},"topic":"memories"},{"id":"family-memories-014","prompt":{"es":"Pensaba que aquello había pasado en verano.","sk":"Myslel som, že sa to stalo v lete."},"reply":{"es":"Yo también, pero en la foto llevamos abrigo.","sk":"Aj ja, ale na fotke máme kabáty."},"topic":"memories"},{"id":"family-memories-015","prompt":{"es":"¿Qué echas de menos de aquella época?","sk":"Čo ti z toho obdobia chýba?"},"reply":{"es":"El tiempo que pasábamos hablando sin mirar el reloj.","sk":"Čas, ktorý sme trávili rozhovorom bez sledovania hodín."},"topic":"memories"},{"id":"family-memories-016","prompt":{"es":"Esta canción sonaba en todos los bares.","sk":"Táto pesnička hrala v každom bare."},"reply":{"es":"Y todavía me sé la letra.","sk":"A ešte stále poznám text."},"topic":"memories"},{"id":"family-memories-017","prompt":{"es":"¿Habías viajado solo antes de aquello?","sk":"Cestoval si predtým sám?"},"reply":{"es":"No, aquella fue la primera vez.","sk":"Nie, vtedy to bolo prvýkrát."},"topic":"memories"},{"id":"family-memories-018","prompt":{"es":"Nunca te he contado cómo conseguí ese trabajo.","sk":"Nikdy som ti nepovedal, ako som získal tú prácu."},"reply":{"es":"Pues ahora quiero saberlo.","sk":"Tak teraz to chcem vedieť."},"topic":"memories"},{"id":"family-memories-019","prompt":{"es":"¿Qué fue lo más difícil al cambiar de país?","sk":"Čo bolo najťažšie pri presťahovaní do inej krajiny?"},"reply":{"es":"No entender las bromas, aunque entendiera las palabras.","sk":"Nerozumieť vtipom, aj keď som rozumel slovám."},"topic":"memories"},{"id":"family-memories-020","prompt":{"es":"No me acuerdo de quién tomó la foto.","sk":"Nepamätám si, kto urobil tú fotku."},"reply":{"es":"Podemos preguntárselo a Luis.","sk":"Môžeme sa opýtať Luisa."},"topic":"memories"},{"id":"family-memories-021","prompt":{"es":"¿Qué costumbre de entonces mantienes?","sk":"Ktorý vtedajší zvyk si si zachoval?"},"reply":{"es":"Sigo escribiendo unas líneas antes de dormir.","sk":"Stále si pred spaním napíšem pár riadkov."},"topic":"memories"},{"id":"family-memories-022","prompt":{"es":"Aquella decisión me cambió la vida.","sk":"To rozhodnutie mi zmenilo život."},"reply":{"es":"¿Lo sabías ya cuando la tomaste?","sk":"Vedel si to už vtedy, keď si sa rozhodol?"},"topic":"memories"},{"id":"family-memories-023","prompt":{"es":"¿Te gustaría volver al lugar donde creciste?","sk":"Chcel by si sa vrátiť tam, kde si vyrastal?"},"reply":{"es":"Sí, aunque sé que ya no será igual.","sk":"Áno, hoci viem, že už to nebude rovnaké."},"topic":"memories"},{"id":"family-memories-024","prompt":{"es":"Yo entonces no sabía lo que estaba pasando.","sk":"Vtedy som nevedel, čo sa deje."},"reply":{"es":"Es normal, te faltaba información.","sk":"Je to prirodzené, nemal si dosť informácií."},"topic":"memories"},{"id":"family-memories-025","prompt":{"es":"¿Hay alguna historia que aún no nos hayas contado?","sk":"Je nejaký príbeh, ktorý si nám ešte nepovedal?"},"reply":{"es":"Unas cuantas; no todo cabe en una tarde.","sk":"Zopár, všetko sa do jedného popoludnia nezmestí."},"topic":"memories"},{"id":"family-interests-001","prompt":{"es":"¿Por dónde vas en la novela?","sk":"Kam si sa dostal v románe?"},"reply":{"es":"Acabo de llegar a la parte del barco.","sk":"Práve som sa dostal k časti s loďou."},"topic":"interests"},{"id":"family-interests-002","prompt":{"es":"No me fío mucho de ese narrador.","sk":"Tomu rozprávačovi veľmi neverím."},"reply":{"es":"Yo tampoco; parece que oculta algo.","sk":"Ani ja, zdá sa, že niečo skrýva."},"topic":"interests"},{"id":"family-interests-003","prompt":{"es":"¿Qué te ha parecido el final?","sk":"Čo si myslíš o závere?"},"reply":{"es":"Me ha sorprendido, pero encaja con el principio.","sk":"Prekvapil ma, ale ladí so začiatkom."},"topic":"interests"},{"id":"family-interests-004","prompt":{"es":"Prefiero leer el capítulo antes de comentarlo.","sk":"Radšej si kapitolu najprv prečítam a až potom ju rozoberiem."},"reply":{"es":"Claro, no te adelanto nada.","sk":"Jasné, nič ti neprezradím."},"topic":"interests"},{"id":"family-interests-005","prompt":{"es":"¿Por qué crees que el capitán sigue buscando?","sk":"Prečo podľa teba kapitán stále hľadá?"},"reply":{"es":"Quizá ya no sabe vivir sin esa búsqueda.","sk":"Možno už nevie žiť bez toho hľadania."},"topic":"interests"},{"id":"family-interests-006","prompt":{"es":"Este personaje me cae fatal.","sk":"Táto postava mi je veľmi nesympatická."},"reply":{"es":"A mí también, aunque está muy bien escrita.","sk":"Aj mne, hoci je veľmi dobre napísaná."},"topic":"interests"},{"id":"family-interests-007","prompt":{"es":"¿Te importa leer ese párrafo en voz alta?","sk":"Prečítaš ten odsek nahlas?"},"reply":{"es":"Sí, luego me dices cómo lo entiendes.","sk":"Áno, potom mi povieš, ako mu rozumieš."},"topic":"interests"},{"id":"family-interests-008","prompt":{"es":"La traducción suena un poco extraña aquí.","sk":"Preklad tu znie trochu zvláštne."},"reply":{"es":"Comparemos con la frase original.","sk":"Porovnajme to s pôvodnou vetou."},"topic":"interests"},{"id":"family-interests-009","prompt":{"es":"¿Has probado a pintar con acuarelas?","sk":"Skúsil si maľovať akvarelom?"},"reply":{"es":"Sí, pero todavía controlo mal el agua.","sk":"Áno, ale vodu ešte neovládam dobre."},"topic":"interests"},{"id":"family-interests-010","prompt":{"es":"No entiendo qué tiene de especial ese cuadro.","sk":"Nerozumiem, čo je na tom obraze výnimočné."},"reply":{"es":"Mira cómo cambia la luz en los rostros.","sk":"Pozri sa, ako sa mení svetlo na tvárach."},"topic":"interests"},{"id":"family-interests-011","prompt":{"es":"¿Qué música te ayuda a concentrarte?","sk":"Aká hudba ti pomáha sústrediť sa?"},"reply":{"es":"Algo instrumental, que no me distraiga la letra.","sk":"Niečo inštrumentálne, aby ma nerozptyľoval text."},"topic":"interests"},{"id":"family-interests-012","prompt":{"es":"Hoy he aprendido un acorde nuevo.","sk":"Dnes som sa naučil nový akord."},"reply":{"es":"Tócalo despacio, quiero escucharlo.","sk":"Zahraj ho pomaly, chcem ho počuť."},"topic":"interests"},{"id":"family-interests-013","prompt":{"es":"¿Leemos versiones distintas del mismo libro?","sk":"Čítame rôzne vydania tej istej knihy?"},"reply":{"es":"Puede ser; en la mía el capítulo tiene otro título.","sk":"Možno, v mojej má kapitola iný názov."},"topic":"interests"},{"id":"family-interests-014","prompt":{"es":"Me gusta cómo discute sin gritar.","sk":"Páči sa mi, ako diskutuje bez kriku."},"reply":{"es":"Sí, hace preguntas en vez de atacar.","sk":"Áno, namiesto útočenia kladie otázky."},"topic":"interests"},{"id":"family-interests-015","prompt":{"es":"¿Tú crees que una máquina puede crear arte?","sk":"Myslíš si, že stroj môže tvoriť umenie?"},"reply":{"es":"Depende de qué entendamos por crear.","sk":"Záleží na tom, čo rozumieme pod tvorbou."},"topic":"interests"},{"id":"family-interests-016","prompt":{"es":"Ese documental me ha dejado pensando.","sk":"Ten dokument ma prinútil premýšľať."},"reply":{"es":"¿Qué pregunta se te ha quedado dando vueltas?","sk":"Ktorá otázka ti zostala v hlave?"},"topic":"interests"},{"id":"family-interests-017","prompt":{"es":"¿Qué te gustaría aprender este año?","sk":"Čo by si sa tento rok chcel naučiť?"},"reply":{"es":"A reconocer las estrellas sin una aplicación.","sk":"Spoznávať hviezdy bez aplikácie."},"topic":"interests"},{"id":"family-interests-018","prompt":{"es":"No comparto la opinión del autor.","sk":"Nesúhlasím s názorom autora."},"reply":{"es":"Aun así, su argumento merece atención.","sk":"Aj tak jeho argument stojí za pozornosť."},"topic":"interests"},{"id":"family-interests-019","prompt":{"es":"¿Me recomiendas algo que no sea muy largo?","sk":"Odporučíš mi niečo, čo nie je veľmi dlhé?"},"reply":{"es":"Tengo un libro de relatos que te puede gustar.","sk":"Mám knihu poviedok, ktorá by sa ti mohla páčiť."},"topic":"interests"},{"id":"family-interests-020","prompt":{"es":"He vuelto a escuchar aquel disco.","sk":"Znovu som si vypočul ten album."},"reply":{"es":"¿Te ha gustado igual que la primera vez?","sk":"Páčil sa ti rovnako ako prvýkrát?"},"topic":"interests"},{"id":"family-interests-021","prompt":{"es":"¿Y si cada uno trae una pregunta para la próxima?","sk":"Čo keby každý nabudúce priniesol jednu otázku?"},"reply":{"es":"Me gusta; así no elegimos siempre el mismo tema.","sk":"Páči sa mi to, aspoň si vždy nevyberieme tú istú tému."},"topic":"interests"},{"id":"family-interests-022","prompt":{"es":"Me cuesta seguir tantos nombres en la historia.","sk":"Ťažko sa orientujem v toľkých menách v príbehu."},"reply":{"es":"Podemos hacer un pequeño mapa de personajes.","sk":"Môžeme si urobiť malú mapu postáv."},"topic":"interests"},{"id":"family-interests-023","prompt":{"es":"¿Te aburren las descripciones largas?","sk":"Nudia ťa dlhé opisy?"},"reply":{"es":"Depende; algunas me hacen ver el lugar.","sk":"Záleží na tom, niektoré mi pomáhajú predstaviť si miesto."},"topic":"interests"},{"id":"family-interests-024","prompt":{"es":"Esta frase tiene dos interpretaciones.","sk":"Táto veta má dva výklady."},"reply":{"es":"Eso es precisamente lo que me interesa.","sk":"Práve to ma zaujíma."},"topic":"interests"},{"id":"family-interests-025","prompt":{"es":"¿Seguimos con el libro o cambiamos de tema?","sk":"Pokračujeme s knihou alebo zmeníme tému?"},"reply":{"es":"Una pregunta más y luego cambiamos.","sk":"Ešte jednu otázku a potom zmeníme."},"topic":"interests"},{"id":"family-outings-001","prompt":{"es":"¿Por aquí se llega al paseo marítimo?","sk":"Dostaneme sa tadiaľto na pobrežnú promenádu?"},"reply":{"es":"Sí, al final de esta calle giramos.","sk":"Áno, na konci tejto ulice odbočíme."},"topic":"outings"},{"id":"family-outings-002","prompt":{"es":"Vamos demasiado deprisa para charlar.","sk":"Ideme príliš rýchlo na rozhovor."},"reply":{"es":"Bajamos el ritmo, no hay prisa.","sk":"Spomalíme, nie je sa kam ponáhľať."},"topic":"outings"},{"id":"family-outings-003","prompt":{"es":"¿Entramos en esa librería un momento?","sk":"Vojdeme na chvíľu do toho kníhkupectva?"},"reply":{"es":"Sí, pero luego recuérdame que salgamos.","sk":"Áno, ale potom mi pripomeň, aby sme vyšli."},"topic":"outings"},{"id":"family-outings-004","prompt":{"es":"Aquí corre mucho aire.","sk":"Tu veľmi fúka."},"reply":{"es":"Busquemos un banco más resguardado.","sk":"Nájdime lavičku viac v závetrí."},"topic":"outings"},{"id":"family-outings-005","prompt":{"es":"¿Te apetece sentarte en una terraza?","sk":"Chceš si sadnúť na terasu?"},"reply":{"es":"Sí, donde no dé el sol de frente.","sk":"Áno, tam, kde slnko nesvieti priamo do tváre."},"topic":"outings"},{"id":"family-outings-006","prompt":{"es":"La ruta del río es más larga.","sk":"Trasa popri rieke je dlhšia."},"reply":{"es":"Pero tiene menos cuestas.","sk":"Ale má menej stúpaní."},"topic":"outings"},{"id":"family-outings-007","prompt":{"es":"¿Has visto ese edificio antes?","sk":"Videl si už tú budovu?"},"reply":{"es":"Sí, pero nunca me había fijado en las ventanas.","sk":"Áno, ale nikdy som si nevšimol okná."},"topic":"outings"},{"id":"family-outings-008","prompt":{"es":"Me he puesto zapatos poco cómodos.","sk":"Obul som si nepohodlné topánky."},"reply":{"es":"Volvemos por el camino corto.","sk":"Vrátime sa kratšou cestou."},"topic":"outings"},{"id":"family-outings-009","prompt":{"es":"¿Llevas agua suficiente?","sk":"Máš dosť vody?"},"reply":{"es":"Sí, y puedo compartir contigo.","sk":"Áno, a môžem sa s tebou podeliť."},"topic":"outings"},{"id":"family-outings-010","prompt":{"es":"Este sitio está mucho más tranquilo entre semana.","sk":"Cez týždeň je tu oveľa pokojnejšie."},"reply":{"es":"Entonces volvamos un martes.","sk":"Tak sa sem vráťme v utorok."},"topic":"outings"},{"id":"family-outings-011","prompt":{"es":"¿Hacemos una foto desde aquí?","sk":"Urobíme odtiaľto fotku?"},"reply":{"es":"Sí, espera a que pase la gente.","sk":"Áno, počkaj, kým prejdú ľudia."},"topic":"outings"},{"id":"family-outings-012","prompt":{"es":"No recordaba que hubiera tantas escaleras.","sk":"Nepamätal som si, že je tu toľko schodov."},"reply":{"es":"Podemos bajar por la otra salida.","sk":"Môžeme zísť druhým východom."},"topic":"outings"},{"id":"family-outings-013","prompt":{"es":"¿Seguimos un poco más o damos la vuelta?","sk":"Pôjdeme ešte trochu alebo sa otočíme?"},"reply":{"es":"Sigamos hasta el puente y volvemos.","sk":"Poďme až k mostu a potom sa vrátime."},"topic":"outings"},{"id":"family-outings-014","prompt":{"es":"Han cerrado el jardín que queríamos ver.","sk":"Zavreli záhradu, ktorú sme chceli vidieť."},"reply":{"es":"Pues aprovechamos para conocer esta plaza.","sk":"Tak využime príležitosť spoznať toto námestie."},"topic":"outings"},{"id":"family-outings-015","prompt":{"es":"¿Te acuerdas de dónde hemos dejado el coche?","sk":"Pamätáš si, kde sme nechali auto?"},"reply":{"es":"Junto a la tienda de bicicletas.","sk":"Vedľa obchodu s bicyklami."},"topic":"outings"},{"id":"family-outings-016","prompt":{"es":"Desde aquí se oye el concierto.","sk":"Odtiaľto počuť koncert."},"reply":{"es":"Nos quedamos a escuchar una canción.","sk":"Zostaňme si vypočuť jednu pesničku."},"topic":"outings"},{"id":"family-outings-017","prompt":{"es":"¿Alquilamos una bici para volver?","sk":"Požičiame si na návrat bicykel?"},"reply":{"es":"Yo prefiero el autobús esta vez.","sk":"Ja tentoraz radšej autobus."},"topic":"outings"},{"id":"family-outings-018","prompt":{"es":"No he mirado la hora en toda la tarde.","sk":"Celé popoludnie som sa nepozrel na hodiny."},"reply":{"es":"Eso suele ser buena señal.","sk":"To zvyčajne býva dobré znamenie."},"topic":"outings"},{"id":"family-outings-019","prompt":{"es":"¿Quieres acercarte al agua?","sk":"Chceš ísť bližšie k vode?"},"reply":{"es":"Sí, pero dejo la bolsa aquí contigo.","sk":"Áno, ale tašku nechám tu pri tebe."},"topic":"outings"},{"id":"family-outings-020","prompt":{"es":"La entrada al museo es por el otro lado.","sk":"Vchod do múzea je z druhej strany."},"reply":{"es":"Rodeamos el edificio entonces.","sk":"Tak obídeme budovu."},"topic":"outings"},{"id":"family-outings-021","prompt":{"es":"¿Nos quedamos a ver la puesta de sol?","sk":"Zostaneme sa pozerať na západ slnka?"},"reply":{"es":"Me apetece, si no tienes frío.","sk":"Rád by som, ak ti nie je zima."},"topic":"outings"},{"id":"family-outings-022","prompt":{"es":"Hemos pasado por alto aquella calle pequeña.","sk":"Prehliadli sme tú malú uličku."},"reply":{"es":"La exploramos a la vuelta.","sk":"Preskúmame ju cestou späť."},"topic":"outings"},{"id":"family-outings-023","prompt":{"es":"¿El paseo te ha resultado demasiado largo?","sk":"Bola pre teba prechádzka pridlhá?"},"reply":{"es":"Un poco, la próxima acortamos.","sk":"Trochu, nabudúce ju skrátime."},"topic":"outings"},{"id":"family-outings-024","prompt":{"es":"Qué diferente se ve todo de noche.","sk":"Ako inak to všetko vyzerá v noci."},"reply":{"es":"Sí, parece otro barrio.","sk":"Áno, akoby to bola iná štvrť."},"topic":"outings"},{"id":"family-outings-025","prompt":{"es":"¿Paramos a comprar algo para llevar?","sk":"Zastavíme sa kúpiť niečo so sebou?"},"reply":{"es":"Sí, así no cocinamos al llegar.","sk":"Áno, aspoň po príchode nebudeme variť."},"topic":"outings"},{"id":"family-travel-001","prompt":{"es":"¿A qué hora sale vuestro tren?","sk":"O koľkej odchádza váš vlak?"},"reply":{"es":"A las diez y cuarto, de la estación del norte.","sk":"O štvrť na jedenásť zo severnej stanice."},"topic":"travel"},{"id":"family-travel-002","prompt":{"es":"He descargado los billetes.","sk":"Stiahol som lístky."},"reply":{"es":"Perfecto, mándame una copia por si acaso.","sk":"Výborne, pre istotu mi pošli kópiu."},"topic":"travel"},{"id":"family-travel-003","prompt":{"es":"¿Llevamos una maleta o dos pequeñas?","sk":"Vezmeme si jeden kufor alebo dva malé?"},"reply":{"es":"Dos pequeñas; será más fácil repartir el peso.","sk":"Dva malé, ľahšie si rozdelíme hmotnosť."},"topic":"travel"},{"id":"family-travel-004","prompt":{"es":"La habitación no estará lista hasta las tres.","sk":"Izba nebude pripravená do tretej."},"reply":{"es":"Podemos dejar las bolsas e ir a comer.","sk":"Môžeme odložiť tašky a ísť sa najesť."},"topic":"travel"},{"id":"family-travel-005","prompt":{"es":"¿Has comprobado desde qué terminal salimos?","sk":"Overil si, z ktorého terminálu odlietame?"},"reply":{"es":"Sí, pero lo volveré a mirar mañana.","sk":"Áno, ale zajtra sa pozriem znovu."},"topic":"travel"},{"id":"family-travel-006","prompt":{"es":"Me gustaría no cambiar de hotel cada noche.","sk":"Nechcel by som meniť hotel každú noc."},"reply":{"es":"De acuerdo, buscamos una base para varios días.","sk":"Súhlasím, nájdime si základňu na viac dní."},"topic":"travel"},{"id":"family-travel-007","prompt":{"es":"¿Quién se encarga de la reserva?","sk":"Kto sa postará o rezerváciu?"},"reply":{"es":"Yo la hago y os paso los datos.","sk":"Ja ju spravím a pošlem vám údaje."},"topic":"travel"},{"id":"family-travel-008","prompt":{"es":"Nos queda una hora de camino.","sk":"Zostáva nám hodina cesty."},"reply":{"es":"Paramos antes si alguien lo necesita.","sk":"Ak niekto potrebuje, zastavíme aj skôr."},"topic":"travel"},{"id":"family-travel-009","prompt":{"es":"¿Queréis desayunar en el hotel?","sk":"Chcete raňajkovať v hoteli?"},"reply":{"es":"Prefiero salir y probar algún sitio cerca.","sk":"Radšej by som vyšiel a skúsil niečo nablízku."},"topic":"travel"},{"id":"family-travel-010","prompt":{"es":"El mapa nos está mandando por un camino raro.","sk":"Mapa nás posiela zvláštnou cestou."},"reply":{"es":"Paremos donde podamos y lo revisamos.","sk":"Zastavme, kde sa dá, a skontrolujme to."},"topic":"travel"},{"id":"family-travel-011","prompt":{"es":"¿Hace falta llevar toallas?","sk":"Treba si vziať uteráky?"},"reply":{"es":"No, el alojamiento las incluye.","sk":"Nie, ubytovanie ich poskytuje."},"topic":"travel"},{"id":"family-travel-012","prompt":{"es":"No quiero cargar cada día de visitas.","sk":"Nechcem mať každý deň plný návštev pamiatok."},"reply":{"es":"Dejamos algunas horas sin plan.","sk":"Necháme si niekoľko hodín bez programu."},"topic":"travel"},{"id":"family-travel-013","prompt":{"es":"¿Podemos sentarnos juntos en el tren?","sk":"Môžeme vo vlaku sedieť spolu?"},"reply":{"es":"Si reservamos ahora, todavía hay sitio.","sk":"Ak si rezervujeme teraz, ešte sú miesta."},"topic":"travel"},{"id":"family-travel-014","prompt":{"es":"Hemos llegado antes de lo previsto.","sk":"Prišli sme skôr, než sme plánovali."},"reply":{"es":"Aprovechamos para orientarnos por el barrio.","sk":"Využime to na zorientovanie sa v štvrti."},"topic":"travel"},{"id":"family-travel-015","prompt":{"es":"¿Tienes apuntada la dirección del apartamento?","sk":"Máš zapísanú adresu apartmánu?"},"reply":{"es":"Sí, también la he guardado sin conexión.","sk":"Áno, uložil som si ju aj na použitie bez internetu."},"topic":"travel"},{"id":"family-travel-016","prompt":{"es":"Esta excursión ocupa el día entero.","sk":"Tento výlet zaberie celý deň."},"reply":{"es":"Entonces mañana hacemos algo más tranquilo.","sk":"Tak zajtra podniknime niečo pokojnejšie."},"topic":"travel"},{"id":"family-travel-017","prompt":{"es":"¿Te importa conducir el primer tramo?","sk":"Odšoféruješ prvý úsek?"},"reply":{"es":"Sí, luego cambiamos en la parada.","sk":"Áno, potom sa na zastávke vymeníme."},"topic":"travel"},{"id":"family-travel-018","prompt":{"es":"Nos han cancelado la visita guiada.","sk":"Zrušili nám prehliadku so sprievodcom."},"reply":{"es":"Preguntemos si podemos ir por nuestra cuenta.","sk":"Opýtajme sa, či môžeme ísť sami."},"topic":"travel"},{"id":"family-travel-019","prompt":{"es":"¿Guardamos algo de efectivo?","sk":"Necháme si nejakú hotovosť?"},"reply":{"es":"Sí, para los sitios que no acepten tarjeta.","sk":"Áno, pre miesta, kde neberú karty."},"topic":"travel"},{"id":"family-travel-020","prompt":{"es":"Me gustaría volver por otra carretera.","sk":"Rád by som sa vrátil inou cestou."},"reply":{"es":"Miremos si añade mucho tiempo.","sk":"Pozrime sa, či to veľmi predĺži cestu."},"topic":"travel"},{"id":"family-travel-021","prompt":{"es":"¿Cómo repartimos los gastos comunes?","sk":"Ako si rozdelíme spoločné výdavky?"},"reply":{"es":"Los apuntamos y hacemos cuentas al final.","sk":"Zapíšeme si ich a na konci sa vyrovnáme."},"topic":"travel"},{"id":"family-travel-022","prompt":{"es":"Tengo la impresión de que hemos traído demasiado.","sk":"Mám pocit, že sme si toho vzali priveľa."},"reply":{"es":"La próxima hacemos una lista más corta.","sk":"Nabudúce si spravíme kratší zoznam."},"topic":"travel"},{"id":"family-travel-023","prompt":{"es":"¿Hay tiempo para visitar a alguien en el camino?","sk":"Máme cestou čas niekoho navštíviť?"},"reply":{"es":"Solo si quedamos con antelación.","sk":"Len ak sa dohodneme vopred."},"topic":"travel"},{"id":"family-travel-024","prompt":{"es":"El regreso se me ha hecho más corto.","sk":"Spiatočná cesta mi pripadala kratšia."},"reply":{"es":"A mí también, ya conocíamos el camino.","sk":"Aj mne, už sme poznali cestu."},"topic":"travel"},{"id":"family-travel-025","prompt":{"es":"¿Qué cambiarías si repitiéramos el viaje?","sk":"Čo by si zmenil, keby sme cestu zopakovali?"},"reply":{"es":"Pasaría más días en un solo lugar.","sk":"Strávil by som viac dní na jednom mieste."},"topic":"travel"},{"id":"family-calls-001","prompt":{"es":"¿Me oyes bien ahora?","sk":"Počuješ ma teraz dobre?"},"reply":{"es":"Sí, antes se cortaba un poco.","sk":"Áno, predtým to trochu vypadávalo."},"topic":"calls"},{"id":"family-calls-002","prompt":{"es":"Te llamo en mal momento, ¿verdad?","sk":"Volám ti nevhod, však?"},"reply":{"es":"Estoy terminando algo; te devuelvo la llamada.","sk":"Niečo dokončujem, zavolám ti späť."},"topic":"calls"},{"id":"family-calls-003","prompt":{"es":"¿Puedes repetir la última parte?","sk":"Zopakuješ poslednú časť?"},"reply":{"es":"Decía que llegaré sobre las siete.","sk":"Hovoril som, že prídem okolo siedmej."},"topic":"calls"},{"id":"family-calls-004","prompt":{"es":"No se te ve la cara.","sk":"Nevidno ti tvár."},"reply":{"es":"Espera, voy a mover la cámara.","sk":"Počkaj, posuniem kameru."},"topic":"calls"},{"id":"family-calls-005","prompt":{"es":"¿Te ha llegado el audio que te mandé?","sk":"Prišla ti hlasová správa, ktorú som ti poslal?"},"reply":{"es":"Sí, pero aún no he podido escucharlo.","sk":"Áno, ale ešte som si ju nemohol vypočuť."},"topic":"calls"},{"id":"family-calls-006","prompt":{"es":"Voy con las manos ocupadas.","sk":"Mám teraz plné ruky."},"reply":{"es":"No te preocupes, hablamos luego.","sk":"Netráp sa, porozprávame sa neskôr."},"topic":"calls"},{"id":"family-calls-007","prompt":{"es":"¿Lo escribes en el grupo para que lo vean todos?","sk":"Napíšeš to do skupiny, aby to všetci videli?"},"reply":{"es":"Sí, así no tengo que repetirlo uno por uno.","sk":"Áno, aspoň to nemusím opakovať každému osobitne."},"topic":"calls"},{"id":"family-calls-008","prompt":{"es":"Creo que se ha congelado la imagen.","sk":"Myslím, že zamrzol obraz."},"reply":{"es":"Salgo de la llamada y vuelvo a entrar.","sk":"Odpojím sa a znovu sa pripojím."},"topic":"calls"},{"id":"family-calls-009","prompt":{"es":"¿Quieres que active los subtítulos?","sk":"Chceš, aby som zapol titulky?"},"reply":{"es":"Sí, me ayudan cuando hay ruido.","sk":"Áno, pomáhajú mi, keď je hluk."},"topic":"calls"},{"id":"family-calls-010","prompt":{"es":"He enviado el mensaje al chat equivocado.","sk":"Poslal som správu do nesprávneho chatu."},"reply":{"es":"Avísales de que era para otra conversación.","sk":"Napíš im, že patrila do iného rozhovoru."},"topic":"calls"},{"id":"family-calls-011","prompt":{"es":"¿Dónde está el enlace para conectarnos?","sk":"Kde je odkaz na pripojenie?"},"reply":{"es":"Te lo acabo de enviar otra vez.","sk":"Práve som ti ho poslal znovu."},"topic":"calls"},{"id":"family-calls-012","prompt":{"es":"Te escucho con eco.","sk":"Počujem ťa s ozvenou."},"reply":{"es":"Me pongo los auriculares.","sk":"Dám si slúchadlá."},"topic":"calls"},{"id":"family-calls-013","prompt":{"es":"¿Me mandas la ubicación cuando llegues?","sk":"Pošleš mi po príchode polohu?"},"reply":{"es":"Sí, te mando el punto exacto.","sk":"Áno, pošlem ti presný bod."},"topic":"calls"},{"id":"family-calls-014","prompt":{"es":"Ahora mismo no puedo leer la pantalla.","sk":"Teraz nemôžem čítať obrazovku."},"reply":{"es":"Te lo digo en voz alta.","sk":"Poviem ti to nahlas."},"topic":"calls"},{"id":"family-calls-015","prompt":{"es":"¿Es urgente o podemos hablar esta noche?","sk":"Súri to alebo sa môžeme porozprávať večer?"},"reply":{"es":"Puede esperar, no hace falta que pares.","sk":"Môže to počkať, nemusíš prerušovať, čo robíš."},"topic":"calls"},{"id":"family-calls-016","prompt":{"es":"No encontraba tu número nuevo.","sk":"Nevedel som nájsť tvoje nové číslo."},"reply":{"es":"Guárdalo ahora y borra el antiguo.","sk":"Ulož si ho teraz a staré vymaž."},"topic":"calls"},{"id":"family-calls-017","prompt":{"es":"¿Podemos seguir por teléfono en vez de escribir?","sk":"Môžeme pokračovať telefonicky namiesto písania?"},"reply":{"es":"Sí, así evitamos malentendidos.","sk":"Áno, vyhneme sa tak nedorozumeniam."},"topic":"calls"},{"id":"family-calls-018","prompt":{"es":"La foto ha salido borrosa.","sk":"Fotka vyšla rozmazaná."},"reply":{"es":"Envíame la original, no la captura.","sk":"Pošli mi originál, nie snímku obrazovky."},"topic":"calls"},{"id":"family-calls-019","prompt":{"es":"¿Quieres que te enseñe a silenciar el grupo?","sk":"Chceš, aby som ti ukázal, ako stíšiť skupinu?"},"reply":{"es":"Sí, prefiero mirar los mensajes cuando pueda.","sk":"Áno, radšej si správy pozriem, keď budem môcť."},"topic":"calls"},{"id":"family-calls-020","prompt":{"es":"Te he llamado sin querer.","sk":"Zavolal som ti nechtiac."},"reply":{"es":"Pues ya que estamos, ¿qué tal todo?","sk":"Tak keď už voláme, ako sa máš?"},"topic":"calls"},{"id":"family-calls-021","prompt":{"es":"¿Has podido abrir el archivo?","sk":"Podarilo sa ti otvoriť súbor?"},"reply":{"es":"Sí, pero no sé dónde se ha guardado.","sk":"Áno, ale neviem, kam sa uložil."},"topic":"calls"},{"id":"family-calls-022","prompt":{"es":"Tengo poca cobertura aquí.","sk":"Mám tu slabý signál."},"reply":{"es":"Llámame cuando llegues a un sitio mejor.","sk":"Zavolaj mi, keď budeš na mieste s lepším signálom."},"topic":"calls"},{"id":"family-calls-023","prompt":{"es":"¿Me confirmas por escrito la hora?","sk":"Potvrdíš mi čas písomne?"},"reply":{"es":"Claro, te lo mando al terminar.","sk":"Jasné, pošlem ti ho, keď skončíme."},"topic":"calls"},{"id":"family-calls-024","prompt":{"es":"No hace falta contestar al momento.","sk":"Netreba odpovedať okamžite."},"reply":{"es":"Gracias, a veces no veo el móvil hasta tarde.","sk":"Ďakujem, niekedy sa na mobil pozriem až neskoro."},"topic":"calls"},{"id":"family-calls-025","prompt":{"es":"¿Nos hacemos una videollamada el domingo?","sk":"Dáme si v nedeľu videohovor?"},"reply":{"es":"Sí, busquemos una hora que nos venga bien a todos.","sk":"Áno, nájdime čas, ktorý vyhovuje všetkým."},"topic":"calls"},{"id":"family-celebrations-001","prompt":{"es":"¿Cómo te gustaría celebrar tu cumpleaños?","sk":"Ako by si chcel osláviť narodeniny?"},"reply":{"es":"Con una comida tranquila, sin grandes preparativos.","sk":"Pokojným obedom, bez veľkých príprav."},"topic":"celebrations"},{"id":"family-celebrations-002","prompt":{"es":"¡Enhorabuena por el resultado!","sk":"Gratulujem k výsledku!"},"reply":{"es":"Gracias, me ha costado bastante llegar hasta aquí.","sk":"Ďakujem, dostať sa až sem ma stálo dosť úsilia."},"topic":"celebrations"},{"id":"family-celebrations-003","prompt":{"es":"¿Abrimos el regalo ahora o después?","sk":"Otvoríme darček teraz alebo potom?"},"reply":{"es":"Ahora, que tengo curiosidad.","sk":"Teraz, som zvedavý."},"topic":"celebrations"},{"id":"family-celebrations-004","prompt":{"es":"No teníais que haber traído nada.","sk":"Nemuseli ste nič nosiť."},"reply":{"es":"Nos hacía ilusión tener un detalle.","sk":"Chceli sme vám urobiť malú radosť."},"topic":"celebrations"},{"id":"family-celebrations-005","prompt":{"es":"¿Quién quiere decir unas palabras?","sk":"Kto chce povedať pár slov?"},"reply":{"es":"Yo, pero prometo ser breve.","sk":"Ja, ale sľubujem, že budem stručný."},"topic":"celebrations"},{"id":"family-celebrations-006","prompt":{"es":"Gracias por organizarlo todo.","sk":"Ďakujem, že si všetko zorganizoval."},"reply":{"es":"Lo hemos hecho entre varios.","sk":"Robili sme to viacerí spolu."},"topic":"celebrations"},{"id":"family-celebrations-007","prompt":{"es":"¿Brindamos antes de empezar?","sk":"Pripijeme si pred začiatkom?"},"reply":{"es":"Sí, por seguir encontrando tiempo para vernos.","sk":"Áno, na to, aby sme si stále našli čas stretnúť sa."},"topic":"celebrations"},{"id":"family-celebrations-008","prompt":{"es":"Este regalo me viene de maravilla.","sk":"Tento darček sa mi veľmi hodí."},"reply":{"es":"Me alegro, no sabía si ya tenías uno.","sk":"Teším sa, nevedel som, či už taký máš."},"topic":"celebrations"},{"id":"family-celebrations-009","prompt":{"es":"¿Te hace ilusión una fiesta sorpresa?","sk":"Potešila by ťa oslava s prekvapením?"},"reply":{"es":"Prefiero saberlo antes, la verdad.","sk":"Úprimne, radšej by som o tom vedel vopred."},"topic":"celebrations"},{"id":"family-celebrations-010","prompt":{"es":"Me ha gustado mucho tu nota.","sk":"Tvoj odkaz ma veľmi potešil."},"reply":{"es":"Quería que supieras cuánto lo valoro.","sk":"Chcel som, aby si vedel, ako si to vážim."},"topic":"celebrations"},{"id":"family-celebrations-011","prompt":{"es":"¿Llevamos algo para compartir?","sk":"Prinesieme niečo pre všetkých?"},"reply":{"es":"Sí, algo fácil de servir.","sk":"Áno, niečo, čo sa ľahko podáva."},"topic":"celebrations"},{"id":"family-celebrations-012","prompt":{"es":"No esperaba que os acordarais.","sk":"Nečakal som, že si spomeniete."},"reply":{"es":"Claro que nos acordamos de la fecha.","sk":"Samozrejme, že si ten dátum pamätáme."},"topic":"celebrations"},{"id":"family-celebrations-013","prompt":{"es":"¿Podemos hacer una celebración pequeña?","sk":"Môžeme spraviť malú oslavu?"},"reply":{"es":"Por supuesto, no hace falta invitar a todo el mundo.","sk":"Samozrejme, nemusíme pozvať všetkých."},"topic":"celebrations"},{"id":"family-celebrations-014","prompt":{"es":"Gracias por venir desde tan lejos.","sk":"Ďakujem, že ste prišli z takej diaľky."},"reply":{"es":"No queríamos perdernos este día.","sk":"Tento deň sme si nechceli nechať ujsť."},"topic":"celebrations"},{"id":"family-celebrations-015","prompt":{"es":"¿Te gustaría elegir tú la música?","sk":"Chcel by si vybrať hudbu ty?"},"reply":{"es":"Sí, prepararé una lista variada.","sk":"Áno, pripravím pestrý zoznam skladieb."},"topic":"celebrations"},{"id":"family-celebrations-016","prompt":{"es":"Ha salido todo mejor de lo previsto.","sk":"Všetko dopadlo lepšie, než sme plánovali."},"reply":{"es":"Y sin correr de un lado a otro.","sk":"A bez behania sem a tam."},"topic":"celebrations"},{"id":"family-celebrations-017","prompt":{"es":"¿Hacemos una foto antes de que se vaya nadie?","sk":"Urobíme fotku skôr, než niekto odíde?"},"reply":{"es":"Buena idea, ahora estamos todos.","sk":"Dobrý nápad, teraz sme tu všetci."},"topic":"celebrations"},{"id":"family-celebrations-018","prompt":{"es":"Tu ayuda ha marcado la diferencia.","sk":"Tvoja pomoc veľmi zavážila."},"reply":{"es":"Me alegra haber podido echar una mano.","sk":"Som rád, že som mohol pomôcť."},"topic":"celebrations"},{"id":"family-celebrations-019","prompt":{"es":"¿Hay algo que no quieras que hagamos en la fiesta?","sk":"Je niečo, čo nechceš, aby sme na oslave robili?"},"reply":{"es":"Por favor, nada de discursos largos.","sk":"Prosím, žiadne dlhé príhovory."},"topic":"celebrations"},{"id":"family-celebrations-020","prompt":{"es":"Me ha emocionado veros juntos.","sk":"Dojalo ma vidieť vás spolu."},"reply":{"es":"A nosotros también nos hacía falta.","sk":"Aj my sme to potrebovali."},"topic":"celebrations"},{"id":"family-celebrations-021","prompt":{"es":"¿Guardamos un trozo de tarta para quien falta?","sk":"Odložíme kúsok torty tomu, kto chýba?"},"reply":{"es":"Sí, lo pongo en una caja.","sk":"Áno, dám ho do škatule."},"topic":"celebrations"},{"id":"family-celebrations-022","prompt":{"es":"No sé cómo darte las gracias.","sk":"Neviem, ako ti poďakovať."},"reply":{"es":"Con que me lo hayas dicho, me basta.","sk":"Stačí mi, že si mi to povedal."},"topic":"celebrations"},{"id":"family-celebrations-023","prompt":{"es":"¿Te apetece repetir esta comida otro año?","sk":"Chcel by si tento obed zopakovať aj o rok?"},"reply":{"es":"Sí, pero repartiendo más el trabajo.","sk":"Áno, ale s lepším rozdelením práce."},"topic":"celebrations"},{"id":"family-celebrations-024","prompt":{"es":"Ha sido un detalle acordarte de lo que me gusta.","sk":"Bolo milé, že si si spomenul na to, čo mám rád."},"reply":{"es":"Me quedé con lo que dijiste la otra vez.","sk":"Zapamätal som si, čo si minule povedal."},"topic":"celebrations"},{"id":"family-celebrations-025","prompt":{"es":"¿Avisamos a quienes no han podido venir?","sk":"Dáme vedieť tým, ktorí nemohli prísť?"},"reply":{"es":"Sí, les mandamos un saludo entre todos.","sk":"Áno, pošleme im spoločný pozdrav."},"topic":"celebrations"},{"id":"family-younger-001","prompt":{"es":"¿Qué es lo que más te gusta de ese juego?","sk":"Čo ťa na tej hre baví najviac?"},"reply":{"es":"Que tengo que pensar una estrategia con otros.","sk":"To, že musím s ostatnými vymyslieť stratégiu."},"topic":"younger"},{"id":"family-younger-002","prompt":{"es":"No conozco esa palabra que has usado.","sk":"Nepoznám slovo, ktoré si použil."},"reply":{"es":"Te explico; se usa mucho entre mis amigos.","sk":"Vysvetlím ti ho, medzi kamarátmi ho často používame."},"topic":"younger"},{"id":"family-younger-003","prompt":{"es":"¿Me enseñas cómo has hecho ese dibujo?","sk":"Ukážeš mi, ako si urobil tú kresbu?"},"reply":{"es":"Sí, empecé por estas líneas.","sk":"Áno, začal som týmito čiarami."},"topic":"younger"},{"id":"family-younger-004","prompt":{"es":"Hoy no tengo ganas de hablar del colegio.","sk":"Dnes nemám chuť hovoriť o škole."},"reply":{"es":"Vale, cuéntame de lo que sí te apetezca.","sk":"Dobre, povedz mi o tom, o čom chceš."},"topic":"younger"},{"id":"family-younger-005","prompt":{"es":"¿Qué música pondrías tú ahora?","sk":"Akú hudbu by si teraz pustil ty?"},"reply":{"es":"Una canción que he descubierto esta semana.","sk":"Pesničku, ktorú som objavil tento týždeň."},"topic":"younger"},{"id":"family-younger-006","prompt":{"es":"No entiendo las reglas todavía.","sk":"Ešte nerozumiem pravidlám."},"reply":{"es":"Jugamos una ronda de prueba.","sk":"Dáme si jedno skúšobné kolo."},"topic":"younger"},{"id":"family-younger-007","prompt":{"es":"¿Quieres ayuda o prefieres intentarlo primero?","sk":"Chceš pomoc alebo to chceš najprv skúsiť sám?"},"reply":{"es":"Déjame probar y luego te pregunto.","sk":"Nechaj ma skúsiť to a potom sa opýtam."},"topic":"younger"},{"id":"family-younger-008","prompt":{"es":"Me parece difícil explicártelo.","sk":"Zdá sa mi ťažké vysvetliť ti to."},"reply":{"es":"Empieza por un ejemplo.","sk":"Začni príkladom."},"topic":"younger"},{"id":"family-younger-009","prompt":{"es":"¿Qué te gustaría preguntarme a mí?","sk":"Čo by si sa chcel opýtať ty mňa?"},"reply":{"es":"¿Qué hacías cuando no sabías qué estudiar?","sk":"Čo si robil, keď si nevedel, čo chceš študovať?"},"topic":"younger"},{"id":"family-younger-010","prompt":{"es":"Esto se me da fatal.","sk":"Toto mi vôbec nejde."},"reply":{"es":"Aún estás aprendiendo; miremos un paso cada vez.","sk":"Ešte sa to učíš, pozrime sa na to po krokoch."},"topic":"younger"},{"id":"family-younger-011","prompt":{"es":"¿Podemos hacer algo sin pantallas un rato?","sk":"Môžeme chvíľu robiť niečo bez obrazoviek?"},"reply":{"es":"Sí, pero elige algo conmigo.","sk":"Áno, ale vyber to spolu so mnou."},"topic":"younger"},{"id":"family-younger-012","prompt":{"es":"Mis amigos no lo hacen así.","sk":"Moji kamaráti to tak nerobia."},"reply":{"es":"Cuéntame cómo lo hacéis vosotros.","sk":"Povedz mi, ako to robíte vy."},"topic":"younger"},{"id":"family-younger-013","prompt":{"es":"¿Te ha pasado algo bueno hoy?","sk":"Stalo sa ti dnes niečo dobré?"},"reply":{"es":"Sí, me he reído mucho con una amiga.","sk":"Áno, veľmi som sa nasmial s kamarátkou."},"topic":"younger"},{"id":"family-younger-014","prompt":{"es":"No quiero salir en esa foto.","sk":"Nechcem byť na tej fotke."},"reply":{"es":"De acuerdo, hacemos otra sin ti.","sk":"Dobre, spravíme inú bez teba."},"topic":"younger"},{"id":"family-younger-015","prompt":{"es":"¿Qué parte del libro te ha dado curiosidad?","sk":"Ktorá časť knihy v tebe vzbudila zvedavosť?"},"reply":{"es":"La que habla de un lugar que no conozco.","sk":"Tá, ktorá hovorí o mieste, ktoré nepoznám."},"topic":"younger"},{"id":"family-younger-016","prompt":{"es":"Me cuesta hablar español delante de todos.","sk":"Ťažko sa mi hovorí po španielsky pred všetkými."},"reply":{"es":"Podemos practicar los dos un rato.","sk":"Môžeme si chvíľu precvičovať vo dvojici."},"topic":"younger"},{"id":"family-younger-017","prompt":{"es":"¿Cómo te gustaría que te ayudáramos?","sk":"Ako by si chcel, aby sme ti pomohli?"},"reply":{"es":"Preguntándome antes de hacerlo por mí.","sk":"Tým, že sa opýtate skôr, než to spravíte za mňa."},"topic":"younger"},{"id":"family-younger-018","prompt":{"es":"He cambiado de idea sobre lo que quiero hacer.","sk":"Zmenil som názor na to, čo chcem robiť."},"reply":{"es":"Es normal; ¿qué te interesa ahora?","sk":"To je prirodzené, čo ťa zaujíma teraz?"},"topic":"younger"},{"id":"family-younger-019","prompt":{"es":"¿Te molesta que te corrija al hablar?","sk":"Prekáža ti, keď ťa pri hovorení opravujem?"},"reply":{"es":"Si me paras cada frase, sí.","sk":"Ak ma zastavíš pri každej vete, tak áno."},"topic":"younger"},{"id":"family-younger-020","prompt":{"es":"Quiero enseñarte algo que he creado.","sk":"Chcem ti ukázať niečo, čo som vytvoril."},"reply":{"es":"Me encantará verlo; dime en qué me fijo.","sk":"Rád si to pozriem, povedz, na čo sa mám zamerať."},"topic":"younger"},{"id":"family-younger-021","prompt":{"es":"¿Por qué te gusta tanto ese personaje?","sk":"Prečo máš tú postavu tak rád?"},"reply":{"es":"Porque cambia de opinión cuando aprende algo.","sk":"Lebo zmení názor, keď sa niečo naučí."},"topic":"younger"},{"id":"family-younger-022","prompt":{"es":"No me sale como en el vídeo.","sk":"Nejde mi to tak ako vo videu."},"reply":{"es":"Puede que hayan grabado muchos intentos.","sk":"Možno nahrali veľa pokusov."},"topic":"younger"},{"id":"family-younger-023","prompt":{"es":"¿Quieres elegir tú el tema de conversación?","sk":"Chceš si vybrať tému rozhovoru ty?"},"reply":{"es":"Sí, pero tú también tienes que responder.","sk":"Áno, ale aj ty musíš odpovedať."},"topic":"younger"},{"id":"family-younger-024","prompt":{"es":"Eso antes no se hacía así, ¿no?","sk":"Kedysi sa to tak nerobilo, však?"},"reply":{"es":"No, y me interesa saber por qué ha cambiado.","sk":"Nie a zaujíma ma, prečo sa to zmenilo."},"topic":"younger"},{"id":"family-younger-025","prompt":{"es":"¿Repetimos juntos lo que hemos aprendido?","sk":"Zopakujeme si spolu, čo sme sa naučili?"},"reply":{"es":"Sí, y luego te hago yo una pregunta.","sk":"Áno, a potom ti ja položím otázku."},"topic":"younger"},{"id":"family-farewells-001","prompt":{"es":"Bueno, nosotros vamos tirando.","sk":"Tak my už pomaly pôjdeme."},"reply":{"es":"Claro, que se os hace tarde.","sk":"Jasné, už je pre vás neskoro."},"topic":"farewells"},{"id":"family-farewells-002","prompt":{"es":"¿Os lleváis algo de lo que ha sobrado?","sk":"Vezmete si niečo z toho, čo zostalo?"},"reply":{"es":"Sí, si tienes un recipiente pequeño.","sk":"Áno, ak máš malú nádobu."},"topic":"farewells"},{"id":"family-farewells-003","prompt":{"es":"Se nos ha pasado la tarde volando.","sk":"Popoludnie nám ubehlo ako voda."},"reply":{"es":"Eso es que estábamos a gusto.","sk":"To znamená, že nám bolo dobre."},"topic":"farewells"},{"id":"family-farewells-004","prompt":{"es":"¿Te aviso cuando lleguemos a casa?","sk":"Dám ti vedieť, keď prídeme domov?"},"reply":{"es":"Sí, aunque sea con un mensaje corto.","sk":"Áno, aj keby len krátkou správou."},"topic":"farewells"},{"id":"family-farewells-005","prompt":{"es":"La próxima invitamos en nuestra casa.","sk":"Nabudúce pozveme my k nám."},"reply":{"es":"Me parece estupendo, ya buscamos fecha.","sk":"To je výborné, potom si nájdeme termín."},"topic":"farewells"},{"id":"family-farewells-006","prompt":{"es":"No te levantes, ya conocemos la salida.","sk":"Nevstávaj, cestu von už poznáme."},"reply":{"es":"Os acompaño hasta la puerta.","sk":"Odprevadím vás k dverám."},"topic":"farewells"},{"id":"family-farewells-007","prompt":{"es":"¿Te devuelvo el libro la semana que viene?","sk":"Vrátim ti knihu budúci týždeň?"},"reply":{"es":"Sin prisa; termina de leerlo.","sk":"Neponáhľaj sa, dočítaj ju."},"topic":"farewells"},{"id":"family-farewells-008","prompt":{"es":"Me ha gustado mucho hablar contigo hoy.","sk":"Dnešný rozhovor s tebou ma veľmi potešil."},"reply":{"es":"A mí también; había ganas de ponernos al día.","sk":"Aj mňa, už sme si potrebovali povedať novinky."},"topic":"farewells"},{"id":"family-farewells-009","prompt":{"es":"¿Lleváis todo o queda alguna bolsa?","sk":"Máte všetko alebo tu zostala taška?"},"reply":{"es":"Falta la que dejamos en la cocina.","sk":"Chýba tá, ktorú sme nechali v kuchyni."},"topic":"farewells"},{"id":"family-farewells-010","prompt":{"es":"Vamos a salir antes de que llueva.","sk":"Vyrazíme skôr, než začne pršať."},"reply":{"es":"Buena idea, el cielo se está cerrando.","sk":"Dobrý nápad, obloha sa zaťahuje."},"topic":"farewells"},{"id":"family-farewells-011","prompt":{"es":"¿Quieres que te acompañemos un tramo?","sk":"Chceš, aby sme ťa kúsok odprevadili?"},"reply":{"es":"Sí, hasta la parada, si os apetece.","sk":"Áno, po zastávku, ak máte chuť."},"topic":"farewells"},{"id":"family-farewells-012","prompt":{"es":"Gracias por hacernos un hueco.","sk":"Ďakujem, že ste si na nás našli čas."},"reply":{"es":"Nos ha venido bien la visita.","sk":"Návšteva nám dobre padla."},"topic":"farewells"},{"id":"family-farewells-013","prompt":{"es":"¿Cuándo podremos repetirlo?","sk":"Kedy si to môžeme zopakovať?"},"reply":{"es":"Aún no lo sé, pero te escribo el jueves.","sk":"Ešte neviem, ale vo štvrtok ti napíšem."},"topic":"farewells"},{"id":"family-farewells-014","prompt":{"es":"Creo que me dejo algo, pero no sé qué.","sk":"Mám pocit, že tu niečo nechávam, ale neviem čo."},"reply":{"es":"Mira si llevas las gafas.","sk":"Pozri sa, či máš okuliare."},"topic":"farewells"},{"id":"family-farewells-015","prompt":{"es":"¿Te mando las fotos de hoy?","sk":"Pošlem ti dnešné fotky?"},"reply":{"es":"Sí, las que salimos juntos, por favor.","sk":"Áno, prosím tie, na ktorých sme spolu."},"topic":"farewells"},{"id":"family-farewells-016","prompt":{"es":"Siento no haber podido quedarme más.","sk":"Mrzí ma, že som nemohol zostať dlhšie."},"reply":{"es":"Lo importante es que hemos podido vernos.","sk":"Dôležité je, že sme sa mohli vidieť."},"topic":"farewells"},{"id":"family-farewells-017","prompt":{"es":"¿Te llamo mañana para saber qué tal?","sk":"Zavolám ti zajtra, ako sa máš?"},"reply":{"es":"Mejor por la tarde, estaré más libre.","sk":"Radšej popoludní, budem mať viac času."},"topic":"farewells"},{"id":"family-farewells-018","prompt":{"es":"Me llevo una idea para seguir pensando.","sk":"Odnášam si jednu myšlienku na premýšľanie."},"reply":{"es":"La retomamos la próxima vez.","sk":"Nabudúce sa k nej vrátime."},"topic":"farewells"},{"id":"family-farewells-019","prompt":{"es":"¿Hay que sacar la basura antes de irnos?","sk":"Treba pred odchodom vyniesť smeti?"},"reply":{"es":"No, nos encargamos nosotros.","sk":"Nie, postaráme sa o to my."},"topic":"farewells"},{"id":"family-farewells-020","prompt":{"es":"Nos vemos pronto, espero.","sk":"Dúfam, že sa čoskoro uvidíme."},"reply":{"es":"Yo también, pero sin agobiarnos con fechas.","sk":"Aj ja, ale netrápme sa termínmi."},"topic":"farewells"},{"id":"family-farewells-021","prompt":{"es":"¿Cierro con llave al salir?","sk":"Mám pri odchode zamknúť?"},"reply":{"es":"Sí, y deja la llave en el buzón.","sk":"Áno, a kľúč nechaj v schránke."},"topic":"farewells"},{"id":"family-farewells-022","prompt":{"es":"Se te queda aquí la chaqueta.","sk":"Zostáva ti tu bunda."},"reply":{"es":"Menos mal que me has avisado.","sk":"Ešteže si ma upozornil."},"topic":"farewells"},{"id":"family-farewells-023","prompt":{"es":"¿Quieres que llevemos a alguien de vuelta?","sk":"Chceš, aby sme niekoho odviezli späť?"},"reply":{"es":"Pregúntale a Sara, va en vuestra dirección.","sk":"Opýtaj sa Sary, ide vaším smerom."},"topic":"farewells"},{"id":"family-farewells-024","prompt":{"es":"Da recuerdos de nuestra parte.","sk":"Pozdravuj od nás."},"reply":{"es":"Se los doy; seguro que les hace ilusión.","sk":"Pozdravím ich, určite ich to poteší."},"topic":"farewells"},{"id":"family-farewells-025","prompt":{"es":"¿Dejamos apuntada la idea para la próxima?","sk":"Zapíšeme si nápad na nabudúce?"},"reply":{"es":"Sí, así no se pierde entre los mensajes.","sk":"Áno, aspoň sa nestratí medzi správami."},"topic":"farewells"}]});
